async function (args) {
  for (const k of ['name', 'bundle_id', 'sku'])
    if (!args[k]) return { error: 'Missing argument: ' + k };
  if (String(args.name).length > 30) return { error: 'name is longer than 30 characters' };
  const platform = String(args.platform || 'IOS').toUpperCase();
  const locale = args.locale || 'en-US';
  const version = String(args.version || '1.0');
  const headers = {
    Accept: 'application/json',
    'Content-Type': 'application/json',
    'X-Csrf-Itc': 'itc'
  };
  const iris = location.origin + '/iris/v1';
  const signedOut = { hint: 'Not signed in to App Store Connect in this browser (sign in, finish 2FA, then retry)' };

  const existing = await fetch(iris + '/apps?' + new URLSearchParams({
    'filter[bundleId]': args.bundle_id, 'fields[apps]': 'name,bundleId,sku'
  }), { credentials: 'include', headers });
  if (existing.status === 401 || existing.status === 403) return { error: 'HTTP ' + existing.status, ...signedOut };
  if (existing.ok) {
    const found = ((await existing.json()).data || []).find((a) => a.attributes.bundleId === args.bundle_id);
    if (found)
      return {
        ok: true, created: false, id: found.id, name: found.attributes.name,
        bundle_id: found.attributes.bundleId, sku: found.attributes.sku,
        url: location.origin + '/apps/' + found.id
      };
  }

  // One compound document, as the web UI sends it: the app, its first
  // version with a primary-language version localization, and the app info
  // carrying the name, all linked by local ids. Two things Apple enforces:
  //  - the name only goes on appInfoLocalizations; on the app itself it is
  //    rejected (409);
  //  - the local ids follow the web UI's own scheme (store-version-<platform>,
  //    new-<platform>VersionLocalization-id, ...). Shorter ids such as
  //    ${new-version} / ${new-versionLoc} were rejected on a fresh bundle id
  //    with "You must provide a value for the relationship
  //    'appStoreVersionLocalizations'", while this scheme created the app.
  const p = platform.toLowerCase();
  const id = (name) => '${' + name + '}';
  const versionId = id('store-version-' + p);
  const versionLocId = id('new-' + p + 'VersionLocalization-id');
  const appInfoId = id('new-appInfo-id');
  const appInfoLocId = id('new-appInfoLocalization-id');
  const payload = {
    data: {
      type: 'apps',
      attributes: { sku: args.sku, primaryLocale: locale, bundleId: args.bundle_id },
      relationships: {
        appStoreVersions: { data: [{ type: 'appStoreVersions', id: versionId }] },
        appInfos: { data: [{ type: 'appInfos', id: appInfoId }] }
      }
    },
    included: [
      {
        type: 'appStoreVersions', id: versionId, attributes: { platform, versionString: version },
        relationships: { appStoreVersionLocalizations: { data: [{ type: 'appStoreVersionLocalizations', id: versionLocId }] } }
      },
      { type: 'appStoreVersionLocalizations', id: versionLocId, attributes: { locale } },
      {
        type: 'appInfos', id: appInfoId,
        relationships: { appInfoLocalizations: { data: [{ type: 'appInfoLocalizations', id: appInfoLocId }] } }
      },
      { type: 'appInfoLocalizations', id: appInfoLocId, attributes: { locale, name: args.name } }
    ]
  };
  const r = await fetch(iris + '/apps', {
    method: 'POST', credentials: 'include', headers, body: JSON.stringify(payload)
  });
  if (r.status === 401 || r.status === 403) {
    const text = await r.text();
    if (r.status === 401 || /NOT_AUTHORIZED|not signed/i.test(text)) return { error: 'HTTP ' + r.status, ...signedOut };
    return { error: 'HTTP ' + r.status, hint: 'This Apple ID may lack the Admin or App Manager role', detail: text.slice(0, 300) };
  }
  const body = await r.json().catch(() => ({}));
  if (!r.ok) {
    const errs = (body.errors || []).map((e) => e.detail || e.title).filter(Boolean);
    return { error: 'App not created (HTTP ' + r.status + ')' + (errs.length ? ': ' + errs.join('; ') : ''), reasons: errs, hint: /bundle/i.test(errs.join(' ')) ? 'Register the bundle id in the developer portal first' : undefined };
  }
  const app = body.data;
  return {
    ok: true, created: true, id: app.id, name: app.attributes.name,
    bundle_id: app.attributes.bundleId, sku: app.attributes.sku,
    url: location.origin + '/apps/' + app.id
  };
}

async function (args) {
  const q = new URLSearchParams({ limit: '200', 'fields[apps]': 'name,bundleId,sku,primaryLocale' });
  if (args.bundle_id) q.set('filter[bundleId]', args.bundle_id);
  const r = await fetch(location.origin + '/iris/v1/apps?' + q, {
    credentials: 'include',
    headers: { Accept: 'application/json', 'X-Csrf-Itc': 'itc' }
  });
  if (r.status === 401 || r.status === 403)
    return { error: 'HTTP ' + r.status, hint: 'Not signed in to App Store Connect in this browser (sign in, finish 2FA, then retry)' };
  if (!r.ok) return { error: 'HTTP ' + r.status, detail: (await r.text()).slice(0, 300) };
  const body = await r.json();
  const apps = (body.data || []).map((a) => ({
    id: a.id,
    name: a.attributes.name,
    bundle_id: a.attributes.bundleId,
    sku: a.attributes.sku,
    primary_locale: a.attributes.primaryLocale,
    url: location.origin + '/apps/' + a.id
  }));
  return { count: apps.length, apps };
}

async function (args) {
  if (!args.bundle_id) return { error: 'Missing argument: bundle_id' };
  const headers = { Accept: 'application/json', 'X-Csrf-Itc': 'itc' };
  const iris = location.origin + '/iris/v1';
  const a = await fetch(iris + '/apps?' + new URLSearchParams({ 'filter[bundleId]': args.bundle_id, 'fields[apps]': 'bundleId' }),
    { credentials: 'include', headers });
  if (a.status === 401 || a.status === 403)
    return { error: 'HTTP ' + a.status, hint: 'Not signed in to App Store Connect in this browser (sign in, finish 2FA, then retry)' };
  if (!a.ok) return { error: 'HTTP ' + a.status };
  const app = ((await a.json()).data || []).find((x) => x.attributes.bundleId === args.bundle_id);
  if (!app) return { error: 'No app with bundle id ' + args.bundle_id, hint: 'Create it with appstoreconnect/app-create' };

  const limit = Math.min(50, Math.max(1, Number(args.limit) || 10));
  const r = await fetch(iris + '/builds?' + new URLSearchParams({
    'filter[app]': app.id, sort: '-uploadedDate', limit: String(limit),
    'fields[builds]': 'version,uploadedDate,processingState,expired,minOsVersion'
  }), { credentials: 'include', headers });
  if (!r.ok) return { error: 'HTTP ' + r.status, detail: (await r.text()).slice(0, 300) };
  const builds = ((await r.json()).data || []).map((b) => ({
    id: b.id,
    build: b.attributes.version,
    state: b.attributes.processingState,
    uploaded: b.attributes.uploadedDate,
    expired: b.attributes.expired,
    min_os: b.attributes.minOsVersion
  }));
  return { app_id: app.id, count: builds.length, builds };
}

async function(args) {
  args = args || {};
  const limit = cgptCount(args.limit, 20, 100);
  const offsetRaw = Number(args.offset);
  const offset = Number.isInteger(offsetRaw) && offsetRaw > 0 ? offsetRaw : 0;

  const qs =
    'offset=' + offset + '&limit=' + limit + '&order=updated';
  const res = await cgptApi('/backend-api/conversations?' + qs);
  if (!res.ok) return { error: res.error, hint: res.hint, status: res.status };

  const items = (res.data && res.data.items) || [];
  // `gizmo_id` is how a conversation says "I live inside this project". The
  // server has no project filter on this endpoint, so filter client-side.
  const wanted = args.project ? String(args.project) : null;
  const filtered = wanted ? items.filter((c) => c.gizmo_id === wanted) : items;

  return {
    count: filtered.length,
    // No `total` on purpose. The endpoint DOES return one, but it is not
    // account-wide: limit=3 reported total:4 on an account whose sidebar lists
    // ~28 conversations. A caller paging until `offset >= total` would stop
    // after the second page believing it was done. A short page — fewer than
    // `limit` rows — is the real end-of-list signal.
    offset: offset,
    project: wanted,
    conversations: filtered.map((c) => ({
      id: c.id,
      title: c.title || null,
      url: 'https://chatgpt.com/c/' + c.id,
      created: c.create_time || null,
      updated: c.update_time || null,
      project: c.gizmo_id || null,
      // The preview line ChatGPT shows in the sidebar — the one field that makes
      // a listing readable without opening anything.
      snippet: c.snippet || null,
      archived: c.is_archived === true,
      starred: c.is_starred === true,
    })),
  };
}

async function(args) {
  // Two sources, deliberately. /api/auth/session is the page's own session
  // endpoint and the only place the bearer token exists; /backend-api/me
  // answers WITHOUT a bearer (cookies alone) and adds the account id and
  // country. Asking both distinguishes "signed out" from "signed in but the
  // token mint is broken", which otherwise look identical.
  const session = await cgptSession();

  let account = null;
  try {
    const r = await fetch('/backend-api/me', { credentials: 'include' });
    if (r.ok) account = await r.json();
  } catch (e) {
    account = null;
  }

  if (!session && !account) {
    return {
      error: 'Not signed in to chatgpt.com',
      hint: 'Open https://chatgpt.com in this browser and sign in, then retry.',
    };
  }

  const user = (session && session.user) || {};
  return {
    signed_in: !!session,
    id: account && account.id ? account.id : user.id || null,
    email: (account && account.email) || user.email || null,
    name: user.name || null,
    country: (account && account.country) || null,
    region: (account && account.region) || null,
    auth_provider: (session && session.authProvider) || null,
    session_expires: (session && session.expires) || null,
    // A signed-in cookie jar whose token mint fails still can't call
    // backend-api — say so rather than reporting a healthy-looking account.
    token_available: !!(session && session.accessToken),
  };
}

async function(args) {
  args = args || {};
  // Projects are "snorlax" gizmos internally — the sidebar endpoint is the only
  // one that lists them. conversations_per_gizmo=0 keeps the response small;
  // without it the server attaches a conversation preview per project.
  const res = await cgptApi(
    '/backend-api/gizmos/snorlax/sidebar?conversations_per_gizmo=0'
  );
  if (!res.ok) return { error: res.error, hint: res.hint, status: res.status };

  const items = (res.data && res.data.items) || [];
  const projects = [];
  for (const item of items) {
    // Doubly nested on purpose: the sidebar wraps a gizmo envelope around the
    // gizmo itself (item.gizmo.gizmo). Skip anything that doesn't match that
    // shape rather than emitting half-built rows.
    const g = item && item.gizmo && item.gizmo.gizmo;
    if (!g || !g.id) continue;
    projects.push({
      id: g.id,
      name: (g.display && g.display.name) || null,
      description: (g.display && g.display.description) || null,
      url: 'https://chatgpt.com/g/' + g.id + '/project',
      updated: g.updated_at || null,
      default_model: g.default_model || null,
    });
  }

  if (args.name) {
    const wanted = String(args.name);
    const hit = projects.find((p) => p.name === wanted);
    if (!hit) {
      return {
        error: 'No project named ' + JSON.stringify(wanted),
        hint:
          'Run `chrome-use site chatgpt/projects` to see the ' +
          projects.length +
          ' project(s) on this account. Matching is exact and case-sensitive.',
        count: 0,
        projects: [],
      };
    }
    return { count: 1, projects: [hit] };
  }

  return { count: projects.length, projects };
}

async function(args) {
  args = args || {}
  const title = String(args.title || '').trim()
  const markdown = String(args.markdown || '')
  if (!title) return { error: 'Missing argument: title' }
  if (!markdown.trim()) return { error: 'Missing argument: markdown' }
  const draftOnly = /^(1|true|yes|y|on)$/i.test(String(args.draft || ''))
  const tagNames = String(args.tags || '').split(/[,，]/).map((s) => s.trim()).filter(Boolean)

  // ---- markdown → html (shared verbatim by csdn/ and zhihu/; a test keeps the copies equal)
  // Covers what blog posts use: headings, paragraphs, fenced code, block
  // quotes, flat or nested lists, rules, GFM tables, bold/italic/strike,
  // inline code, links, images. Raw HTML in the source is escaped, not passed.
  const mdToHtml = (src, codeBlock) => {
    const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
    const inline = (text) => {
      const slots = []
      const keep = (html) => '\u0000' + (slots.push(html) - 1) + '\u0000'
      let s = String(text).replace(/(`+)([^`]|[^`][\s\S]*?[^`])\1(?!`)/g, (m, t, c) => keep('<code>' + esc(c.trim()) + '</code>'))
      s = s.replace(/!\[([^\]]*)\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g, (m, alt, url) => keep('<img src="' + esc(url) + '" alt="' + esc(alt) + '">'))
      s = s.replace(/\[([^\]]+)\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g, (m, label, url) => keep('<a href="' + esc(url) + '">' + inline(label) + '</a>'))
      s = s.replace(/<(https?:\/\/[^\s>]+)>/g, (m, url) => keep('<a href="' + esc(url) + '">' + esc(url) + '</a>'))
      s = esc(s)
      s = s.replace(/\*\*(?=\S)([\s\S]*?\S)\*\*/g, '<strong>$1</strong>').replace(/__(?=\S)([\s\S]*?\S)__/g, '<strong>$1</strong>')
      s = s.replace(/~~(?=\S)([\s\S]*?\S)~~/g, '<del>$1</del>')
      s = s.replace(/(^|[^*\w])\*(?=\S)([^*]*?\S)\*(?!\*)/g, '$1<em>$2</em>')
      s = s.replace(/(^|[^_\w])_(?=\S)([^_]*?\S)_(?![_\w])/g, '$1<em>$2</em>')
      s = s.replace(/ {2,}\n/g, '<br>\n')
      return s.replace(/\u0000(\d+)\u0000/g, (m, i) => slots[Number(i)])
    }
    const cells = (row) => row.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim())
    const blocks = (lines) => {
      const out = []
      let i = 0
      const isFence = (l) => /^\s{0,3}(```|~~~)/.test(l)
      const isHr = (l) => /^\s{0,3}([-*_])(\s*\1){2,}\s*$/.test(l)
      const isHead = (l) => /^\s{0,3}#{1,6}(\s|$)/.test(l)
      const isQuote = (l) => /^\s{0,3}>/.test(l)
      const isItem = (l) => /^\s{0,3}([-*+]|\d{1,9}[.)])\s+/.test(l)
      const isTable = (k) => /\|/.test(lines[k] || '') && /^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)*\|?\s*$/.test(lines[k + 1] || '')
      while (i < lines.length) {
        const line = lines[i]
        if (!line.trim()) { i++; continue }
        if (isFence(line)) {
          const fence = line.trim().slice(0, 3)
          const lang = line.trim().slice(3).trim().split(/\s+/)[0] || ''
          const body = []
          i++
          while (i < lines.length && !lines[i].trim().startsWith(fence)) body.push(lines[i++])
          i++
          out.push(codeBlock(lang, esc(body.join('\n'))))
          continue
        }
        if (isHead(line)) {
          const m = line.trim().match(/^(#{1,6})\s*(.*?)\s*#*\s*$/)
          out.push('<h' + m[1].length + '>' + inline(m[2]) + '</h' + m[1].length + '>')
          i++
          continue
        }
        if (isHr(line)) { out.push('<hr>'); i++; continue }
        if (isQuote(line)) {
          const body = []
          while (i < lines.length && lines[i].trim() && isQuote(lines[i])) body.push(lines[i++].replace(/^\s{0,3}>\s?/, ''))
          out.push('<blockquote>' + blocks(body) + '</blockquote>')
          continue
        }
        if (isTable(i)) {
          const head = cells(lines[i])
          i += 2
          const rows = []
          while (i < lines.length && lines[i].trim() && /\|/.test(lines[i])) rows.push(cells(lines[i++]))
          out.push('<table><thead><tr>' + head.map((c) => '<th>' + inline(c) + '</th>').join('') + '</tr></thead><tbody>' +
            rows.map((r) => '<tr>' + r.map((c) => '<td>' + inline(c) + '</td>').join('') + '</tr>').join('') + '</tbody></table>')
          continue
        }
        if (isItem(line)) {
          const ordered = /^\s{0,3}\d/.test(line)
          const indent = line.match(/^\s*/)[0].length
          const items = []
          while (i < lines.length) {
            const l = lines[i]
            const ind = l.match(/^\s*/)[0].length
            if (isItem(l) && ind <= indent + 1) {
              if (/^\s{0,3}\d/.test(l) !== ordered) break
              items.push([l.replace(/^\s*([-*+]|\d{1,9}[.)])\s+/, '')])
              i++
            } else if (l.trim() && items.length && (ind > indent || !(isFence(l) || isHead(l) || isQuote(l) || isHr(l)))) {
              items[items.length - 1].push(ind > indent ? l.slice(Math.min(ind, indent + 2)) : l)
              i++
            } else if (!l.trim() && i + 1 < lines.length && lines[i + 1].match(/^\s*/)[0].length > indent && lines[i + 1].trim()) {
              items[items.length - 1].push('')
              i++
            } else break
          }
          const tag = ordered ? 'ol' : 'ul'
          out.push('<' + tag + '>' + items.map((it) => {
            const inner = blocks(it)
            // A tight item is one paragraph: drop its <p> so lists render compact.
            return '<li>' + (/^<p>[\s\S]*<\/p>$/.test(inner) && inner.indexOf('<p>', 1) < 0 ? inner.slice(3, -4) : inner) + '</li>'
          }).join('') + '</' + tag + '>')
          continue
        }
        const para = []
        while (i < lines.length && lines[i].trim() && !isFence(lines[i]) && !isHead(lines[i]) && !isQuote(lines[i]) && !isHr(lines[i]) && !isItem(lines[i]) && !isTable(i)) para.push(lines[i++])
        out.push('<p>' + inline(para.join('\n')) + '</p>')
      }
      return out.join('')
    }
    return blocks(String(src || '').replace(/\r\n?/g, '\n').split('\n'))
  }
  // ---- end markdown → html

  // Every bizapi.csdn.net call carries x-ca-key / x-ca-nonce / x-ca-signature
  // headers. The editor signs them in its own request client; find that client
  // in the editor's webpack registry (through the module that saves articles)
  // and send through it, instead of re-implementing the signature here.
  const findClient = (win) => {
    const chunks = win && win.webpackChunkcsdnEdit
    if (!chunks || typeof chunks.push !== 'function') return null
    let req = null
    chunks.push([[Symbol('chrome-use-csdn')], {}, (r) => { req = r }])
    if (!req || !req.m) return null
    for (const id of Object.keys(req.m)) {
      let src
      try { src = String(req.m[id]) } catch (e) { continue }
      if (!src.includes('mdeditor/saveArticle')) continue
      const m = src.match(/(\w+)=\w\((\d+)\)[^]*?\b\1\.(\w+)\.request\(\{method:"POST",url:"".concat\("https:\/\/bizapi\.csdn\.net\/blog-console-api\/","v3\/mdeditor\/saveArticle"/)
      if (!m) continue
      let client = null
      try { client = req(Number(m[2]))[m[3]] } catch (e) { client = null }
      if (client && typeof client.request === 'function') return client
    }
    return null
  }
  if (!/(^|\.)editor\.csdn\.net$/.test(location.hostname)) {
    return { error: 'Not on editor.csdn.net', hint: 'Run it through `chrome-use site`, which opens editor.csdn.net first.' }
  }
  // chrome-use lands on https://editor.csdn.net/, which is not the editor. Load
  // the editor (/md/) in a hidden same-origin frame and borrow its client; if
  // this tab already is the editor, use it directly.
  let client = findClient(window)
  let frame = null
  if (!client) {
    frame = document.createElement('iframe')
    frame.style.cssText = 'position:fixed;width:1px;height:1px;left:-10px;top:-10px;opacity:0;border:0'
    frame.src = 'https://editor.csdn.net/md/?not_checkout=1'
    document.body.appendChild(frame)
    for (let n = 0; n < 40 && !client; n++) {
      await new Promise((r) => setTimeout(r, 150))
      try { client = findClient(frame.contentWindow) } catch (e) { client = null }
    }
  }
  if (!client) {
    if (frame) frame.remove()
    return { error: 'Cannot find the CSDN editor request client', hint: 'editor.csdn.net/md/ did not load or changed its bundle; this adapter needs updating.' }
  }
  try {
    return await publish()
  } finally {
    if (frame) frame.remove()
  }

  async function publish() {
    const send = async (config) => {
      try {
        const r = await client.request(Object.assign({ withCredentials: true }, config), false, false)
        const body = r && r.body
        if (!body || body.code !== 200) return { ok: false, body, error: (body && (body.msg || body.message)) || 'HTTP ' + (r && r.status) }
        return { ok: true, data: body.data }
      } catch (e) {
        const body = e && e.body
        return { ok: false, body, error: (body && (body.msg || body.message)) || (e && e.message) || String(e) }
      }
    }

    const info = await send({ method: 'GET', url: 'https://bizapi.csdn.net/blog-console-api/v3/editor/getBaseInfo' })
    if (!info.ok) return { error: 'Not signed in to CSDN (' + info.error + ')', hint: 'Log in at https://passport.csdn.net in this browser, then retry.' }
    const user = info.data || {}

    // Tags: exact (case-insensitive) matches from CSDN's own tag search.
    const found = await Promise.all(tagNames.map((name) => send({
      method: 'POST',
      url: 'https://bizapi.csdn.net/blog/phoenix/console/v1/tag/search-recommend-tag',
      body: { key: name, page: 0, page_size: 50, platform: 'pc' },
    })))
    const usedTags = []
    const skippedTags = []
    tagNames.forEach((name, i) => {
      const rows = (found[i].ok && Array.isArray(found[i].data)) ? found[i].data : []
      const hit = rows.find((t) => String(t) === name) || rows.find((t) => String(t).toLowerCase() === name.toLowerCase())
      if (hit && usedTags.length < 5 && !usedTags.includes(hit)) usedTags.push(hit)
      else skippedTags.push(name)
    })
    if (!draftOnly && !usedTags.length) {
      return { error: 'None of the tags exist on CSDN: ' + tagNames.join(', '), hint: 'Publishing needs at least one existing tag; this account (blog level ' + user.blog_level + ') cannot create new ones.' }
    }

    const content = String(args.html || '') || mdToHtml(markdown, (lang, code) =>
      '<pre><code' + (lang ? ' class="prism language-' + lang.replace(/[^\w+#.-]/g, '') + '"' : '') + '>' + code + '</code></pre>')

    // Field for field what the editor's own publish sends (status 0 = publish,
    // 2 = draft; type original = 原创).
    const saved = await send({
      method: 'POST',
      url: 'https://bizapi.csdn.net/blog-console-api/v3/mdeditor/saveArticle',
      body: {
        id: /^\d+$/.test(String(args.id || '').trim()) ? String(args.id).trim() : '',
        title,
        markdowncontent: markdown,
        content,
        readType: 'public',
        level: 0,
        tags: usedTags.join(','),
        status: draftOnly ? 2 : 0,
        categories: String(args.category || '').split(/[,，]/).map((s) => s.trim()).filter(Boolean).join(','),
        type: 'original',
        original_link: '',
        authorized_status: false,
        Description: Array.from(String(args.summary || '')).slice(0, 256).join(''),
        resource_url: '',
        not_auto_saved: '1',
        source: 'pc_mdeditor',
        cover_images: [],
        cover_type: 0,
        is_new: 1,
        vote_id: 0,
        resource_id: '',
        pubStatus: draftOnly ? 'draft' : 'publish',
        creation_statement: 0,
      },
    })
    if (!saved.ok) {
      return {
        error: 'CSDN refused the ' + (draftOnly ? 'draft' : 'publish') + ': ' + saved.error,
        hint: 'Nothing to retry blindly: check https://mp.csdn.net/mp_blog/manage/article first.',
        tags: usedTags,
        skipped_tags: skippedTags,
      }
    }
    const d = saved.data || {}
    const id = String(d.article_id || d.id || '')
    return {
      ok: true,
      id,
      url: draftOnly
        ? 'https://editor.csdn.net/md/?articleId=' + id
        : d.url || 'https://blog.csdn.net/' + (user.name || '') + '/article/details/' + id,
      // CSDN reviews new posts; it may stay hidden for a few minutes.
      status: draftOnly ? 'draft' : 'published',
      tags: usedTags,
      skipped_tags: skippedTags,
    }
  }
}

