async function(args) {
  args = args || {}
  const limit = Math.min(Math.max(parseInt(args.limit, 10) || 50, 1), 500)
  const visibility = String(args.visibility || 'all').toLowerCase()
  if (!['all', 'public', 'private'].includes(visibility)) {
    return { error: 'Bad visibility: ' + args.visibility, hint: 'Use all, public or private' }
  }
  const num = (v) => (v == null || v === '' || !Number.isFinite(Number(v)) ? null : Number(v))
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

  // The server returns about six works per page whatever page_size says, so a
  // full account is dozens of requests. A dropped request ("Failed to fetch")
  // is retried once; if it fails again, the works so far come back with the
  // cursor to resume from instead of losing the whole call.
  async function page(cursor) {
    const url = '/janus/douyin/creator/pc/work_list?page_size=20&status=0&max_cursor=' + encodeURIComponent(cursor)
    let lastErr = null
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        const resp = await fetch(url, { credentials: 'include' })
        if (!resp.ok) { lastErr = 'HTTP ' + resp.status; break }
        const d = await resp.json()
        if (d.status_code !== 0) { lastErr = 'status_code ' + d.status_code + (d.status_msg ? ' ' + d.status_msg : ''); break }
        return { ok: true, d }
      } catch (e) {
        lastErr = 'Network error: ' + (e && e.message || e)
        await sleep(800)
      }
    }
    return { ok: false, error: lastErr }
  }

  const shape = (a) => {
    const s = a.statistics || {}
    const st = a.status || {}
    const priv = Boolean(st.is_private || st.self_see || (st.private_status && st.private_status !== 0))
    return {
      aweme_id: String(a.aweme_id),
      title: a.item_title || (a.desc || '').split('\n')[0].slice(0, 80),
      desc: a.desc || '',
      created_at: a.create_time ? new Date(Number(a.create_time) * 1000).toISOString() : null,
      duration_sec: a.duration ? Math.round(Number(a.duration) / 1000) : null,
      visibility: priv ? 'private' : 'public',
      in_review: Boolean(st.in_reviewing),
      plays: num(s.play_count),
      likes: num(s.digg_count),
      comments: num(s.comment_count),
      shares: num(s.share_count),
      collects: num(s.collect_count),
      url: 'https://www.douyin.com/video/' + a.aweme_id,
    }
  }

  const works = []
  let cursor = args.cursor != null && args.cursor !== '' ? String(args.cursor) : '0'
  let total = null
  let hasMore = true
  let error = null
  for (let i = 0; i < 120 && hasMore && works.length < limit; i++) {
    const r = await page(cursor)
    if (!r.ok) { error = r.error; break }
    const d = r.d
    if (total == null) total = num(d.total)
    for (const a of d.aweme_list || []) {
      const w = shape(a)
      if (visibility === 'all' || w.visibility === visibility) works.push(w)
      if (works.length >= limit) break
    }
    hasMore = Boolean(d.has_more) && d.max_cursor != null && String(d.max_cursor) !== cursor
    cursor = String(d.max_cursor)
  }

  if (error && works.length === 0) {
    return { error, hint: error.startsWith('HTTP 4') || error.startsWith('status_code') ? 'Open https://creator.douyin.com and sign in, then retry' : 'Retry; pass --cursor to resume' }
  }
  return {
    count: works.length,
    total,
    has_more: hasMore,
    next_cursor: hasMore ? cursor : null,
    error: error || undefined,
    works,
  }
}

async function(args) {
  args = args || {}
  const W = window
  const D = document
  const MANAGE_PATH = '/creator-micro/content/manage'
  const MANAGE_URL = 'https://creator.douyin.com' + MANAGE_PATH
  const WORK_LIST = '/janus/douyin/creator/pc/work_list?status=0&count=20&scene=star_atlas&device_platform=android&aid=1128&max_cursor='
  const MAX_PAGES = 10
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
  const textOf = (node) => ((node && (node.innerText || node.textContent)) || '').trim()
  const normalize = (value) => String(value || '').replace(/\s+/g, ' ').trim()
  const idOf = (value) => (value == null ? '' : String(value))

  const targetId = String(args.aweme_id == null ? '' : args.aweme_id).trim()
  if (!targetId) return { error: 'Missing argument: aweme_id', hint: 'Pass the work id, e.g. chrome-use site douyin/delete 7694857245896576275 --until-done' }
  if (!/^\d+$/.test(targetId)) return { error: 'aweme_id must be a numeric id, got ' + JSON.stringify(targetId), hint: 'List ids with chrome-use site douyin-creator/works' }

  // Douyin sends 64-bit ids as bare JSON numbers, which JSON.parse rounds
  // (7694857245896576275 -> 7694857245896576000). Quote every integer that is
  // not a safe JS integer before parsing, so ids come back as exact strings.
  function quoteUnsafeIntegers(text) {
    const src = String(text)
    let out = ''
    let i = 0
    let last = 0
    while (i < src.length) {
      const c = src[i]
      if (c === '"') {
        i += 1
        while (i < src.length && src[i] !== '"') i += src[i] === '\\' ? 2 : 1
        i += 1
        continue
      }
      if (c === '-' || (c >= '0' && c <= '9')) {
        const start = i
        i += 1
        while (i < src.length && /[0-9.eE+-]/.test(src[i])) i += 1
        const token = src.slice(start, i)
        if (/^-?\d+$/.test(token) && !Number.isSafeInteger(Number(token))) {
          out += src.slice(last, start) + '"' + token + '"'
          last = i
        }
        continue
      }
      i += 1
    }
    return out + src.slice(last)
  }
  const parseJsonKeepingBigInts = (text) => JSON.parse(quoteUnsafeIntegers(text))

  // The card UI lives on 作品管理. Open it and come back: the navigation ends
  // this run, and --until-done reruns the command there.
  if (String(W.location.pathname || '').indexOf(MANAGE_PATH) !== 0) {
    setTimeout(() => W.location.assign(MANAGE_URL), 800)
    return { status: 'navigating', url: MANAGE_URL, retryAfterMs: 4000, hint: 'Opening 作品管理; run the same command again there, or pass --until-done' }
  }

  // The target in work_list, paged newest first. `index` counts works across
  // pages, which is where its card sits in the 全部作品 list.
  async function loadTarget() {
    let cursor = '0'
    let seen = 0
    for (let page = 0; page < MAX_PAGES; page += 1) {
      let payload
      try {
        const res = await fetch(WORK_LIST + encodeURIComponent(cursor), { credentials: 'include' })
        if (!res.ok) return { ok: false, reason: 'work_list_http_' + res.status }
        payload = parseJsonKeepingBigInts(await res.text())
      } catch (e) {
        return { ok: false, reason: 'work_list_failed', message: String((e && e.message) || e) }
      }
      if (payload.status_code != null && payload.status_code !== 0) {
        return { ok: false, reason: 'work_list_status', status_code: payload.status_code, status_msg: payload.status_msg }
      }
      const list = Array.isArray(payload.aweme_list) ? payload.aweme_list : []
      const matches = list
        .map((entry, i) => ({ entry, index: seen + i }))
        .filter(({ entry }) => idOf(entry.aweme_id) === targetId || idOf(entry.item_id) === targetId)
      if (matches.length > 1) return { ok: false, reason: 'target_not_unique', count: matches.length }
      if (matches.length === 1) {
        const { entry, index } = matches[0]
        const item = { aweme_id: idOf(entry.aweme_id), item_id: idOf(entry.item_id) }
        const title = normalize(entry.desc || entry.caption || entry.title || entry.item_title || '')
        // What a work card shows: its title, or the first line of its text.
        const key = normalize(entry.item_title || String(entry.desc || entry.caption || entry.title || '').split('\n')[0]).slice(0, 12)
        return { ok: true, item, index, listCount: seen + list.length, title, key }
      }
      seen += list.length
      const next = payload.max_cursor == null ? '' : String(payload.max_cursor)
      if (!payload.has_more || !next || next === cursor) break
      cursor = next
    }
    return { ok: false, reason: 'not_found', count: seen }
  }

  function visibleWorkCards() {
    const candidates = Array.from(D.querySelectorAll('[class*="video-card"]')).filter((element) => {
      const text = normalize(textOf(element))
      return text.includes('删除作品') && text.includes('继续编辑')
    })
    return candidates.filter((candidate) => !candidates.some((other) => other !== candidate && other.contains(candidate)))
  }

  // The card for the target. With a title: the only card showing it; among
  // several, the one whose markup carries the id, else the one at the
  // work_list index. Without a title: the only card whose markup carries the
  // id, else the index once every listed work is rendered.
  function findCard(cards, target) {
    const ids = [target.item.aweme_id, target.item.item_id].filter(Boolean)
    const carriesId = (card) => ids.some((id) => String(card.outerHTML || '').includes(id))
    const atIndex = cards[target.index] || null
    if (target.key) {
      const byTitle = cards.filter((card) => normalize(textOf(card)).includes(target.key))
      if (byTitle.length === 1) return byTitle[0]
      const byId = byTitle.filter(carriesId)
      if (byId.length === 1) return byId[0]
      return byTitle.includes(atIndex) ? atIndex : null
    }
    const byId = cards.filter(carriesId)
    if (byId.length === 1) return byId[0]
    return cards.length >= target.listCount ? atIndex : null
  }

  const target = await loadTarget()
  if (!target.ok) {
    const fail = Object.assign({ error: target.reason, aweme_id: targetId }, target)
    delete fail.ok
    if (target.reason === 'not_found') fail.hint = 'No work with this id in the account\'s work list (already deleted, or not this account\'s); nothing was clicked. List ids with chrome-use site douyin-creator/works'
    else fail.hint = 'Nothing was deleted. Open https://creator.douyin.com and sign in, then retry'
    return fail
  }

  // The page renders its cards after load.
  for (let wait = 0; wait < 20 && visibleWorkCards().length === 0; wait += 1) await sleep(500)

  const allTab = Array.from(D.querySelectorAll('button,[role="button"],span,div'))
    .find((element) => /^全部作品$/.test(normalize(textOf(element))))
  if (allTab) allTab.click()
  await sleep(1000)

  const ids = { aweme_id: target.item.aweme_id, item_id: target.item.item_id }
  for (let attempt = 0; attempt < 20; attempt += 1) {
    const cards = visibleWorkCards()
    const card = findCard(cards, target)
    if (card) {
      const deleteButton = Array.from(card.querySelectorAll('button,[role="button"],span,div'))
        .find((element) => /^删除作品$/.test(normalize(textOf(element))))
      if (!deleteButton) return Object.assign({ error: 'delete_button_not_found', index: target.index, cardCount: cards.length, hint: 'Nothing was deleted' }, ids)
      deleteButton.click()
      await sleep(800)
      const confirmButton = Array.from(D.querySelectorAll('button,[role="button"]'))
        .find((element) => ['确定', '确认', '删除'].includes(normalize(textOf(element))))
      if (!confirmButton) return Object.assign({ error: 'confirm_button_not_found', hint: 'The delete dialog did not show a confirm button; nothing was confirmed' }, ids)
      confirmButton.click()
      for (let wait = 0; wait < 20; wait += 1) {
        await sleep(500)
        const after = await loadTarget()
        if (!after.ok && after.reason === 'not_found') {
          return Object.assign({ ok: true, status: 'deleted', title: target.title }, ids)
        }
      }
      return Object.assign({ error: 'delete_not_confirmed', hint: 'Confirm was clicked but the work is still in work_list; check 作品管理 before retrying' }, ids)
    }
    // Cards load as the list scrolls; bring the last one into view.
    const lastCard = cards[cards.length - 1]
    if (lastCard && lastCard.scrollIntoView) lastCard.scrollIntoView({ block: 'end' })
    await sleep(500)
  }
  return Object.assign({
    error: 'card_not_found',
    index: target.index,
    listCount: target.listCount,
    cardCount: visibleWorkCards().length,
    hint: 'No card on 作品管理 shows this work\'s title; nothing was clicked',
  }, ids)
}

async function(args) {
  args = args || {}
  const BASE = 'https://creator.douyin.com'
  const MIN_OFFSET = 7200 // 2 hours
  const MAX_OFFSET = 14 * 86400 // 14 days

  const awemeId = String(args.aweme_id == null ? '' : args.aweme_id).trim()
  if (!awemeId) return { error: 'Missing argument: aweme_id', hint: 'Pass the work id, e.g. chrome-use site douyin/update 7694857245896576275 --caption "..."' }
  if (!/^\d+$/.test(awemeId)) return { error: 'aweme_id must be a numeric id, got ' + JSON.stringify(awemeId), hint: 'List ids with chrome-use site douyin-creator/works' }
  const reschedule = String(args.reschedule == null ? '' : args.reschedule).trim()
  const caption = args.caption == null ? '' : String(args.caption)
  if (!reschedule && !caption) return { error: 'Nothing to update', hint: 'Pass --reschedule <time> and/or --caption <text>' }

  let publishTime = null
  if (reschedule) {
    publishTime = /^\d+$/.test(reschedule) ? Number(reschedule) : Math.floor(new Date(reschedule).getTime() / 1000)
    if (!Number.isFinite(publishTime)) return { error: 'Bad --reschedule: ' + JSON.stringify(reschedule), hint: 'Use ISO 8601 (2026-10-20T20:00:00+08:00) or Unix seconds' }
    const now = Math.floor(Date.now() / 1000)
    if (publishTime < now + MIN_OFFSET) return { error: 'The new publish time must be at least 2 hours from now', publish_time: publishTime }
    if (publishTime > now + MAX_OFFSET) return { error: 'The new publish time must be at most 14 days from now', publish_time: publishTime }
  }

  // Douyin sends 64-bit ids as bare JSON numbers, which JSON.parse rounds.
  // Quote every integer that is not a safe JS integer before parsing.
  function quoteUnsafeIntegers(text) {
    const src = String(text)
    let out = ''
    let i = 0
    let last = 0
    while (i < src.length) {
      const c = src[i]
      if (c === '"') {
        i += 1
        while (i < src.length && src[i] !== '"') i += src[i] === '\\' ? 2 : 1
        i += 1
        continue
      }
      if (c === '-' || (c >= '0' && c <= '9')) {
        const start = i
        i += 1
        while (i < src.length && /[0-9.eE+-]/.test(src[i])) i += 1
        const token = src.slice(start, i)
        if (/^-?\d+$/.test(token) && !Number.isSafeInteger(Number(token))) {
          out += src.slice(last, start) + '"' + token + '"'
          last = i
        }
        continue
      }
      i += 1
    }
    return out + src.slice(last)
  }

  const authLike = (code, msg) => code === 401 || code === 403 || /login|cookie|auth|captcha|verify|forbidden|permission|登录|登陆|权限|验证|验证码/i.test(String(msg || ''))

  // POST a JSON body from the page (cookies and signing come with it).
  async function post(path, body) {
    let res
    let text
    try {
      res = await fetch(BASE + path, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })
      text = await res.text()
    } catch (e) {
      return { ok: false, error: 'Network error: ' + String((e && e.message) || e) }
    }
    if (!String(text || '').trim()) {
      return res.ok ? { ok: false, error: 'Empty response from ' + path, hint: 'The endpoint may have been retired or may now need signed parameters' } : { ok: false, error: 'HTTP ' + res.status + ' from ' + path }
    }
    let d
    try {
      d = JSON.parse(quoteUnsafeIntegers(text))
    } catch (e) {
      return { ok: false, error: 'Unreadable response from ' + path + ' (HTTP ' + res.status + ')' }
    }
    if (!d || typeof d !== 'object' || Array.isArray(d)) return { ok: false, error: 'Malformed response from ' + path }
    if ('status_code' in d && d.status_code !== 0) {
      const msg = d.status_msg || d.message || 'unknown error'
      return { ok: false, error: 'Douyin API error ' + d.status_code + ' at ' + path + ': ' + msg, loginRequired: authLike(d.status_code, msg) || undefined }
    }
    return { ok: true, data: d }
  }

  const updated = []
  const fail = (r) => ({
    error: r.error,
    hint: r.loginRequired ? 'Open https://creator.douyin.com and sign in, then retry' : r.hint || (updated.length ? 'Already updated: ' + updated.join(', ') + '; the rest was not applied' : 'Nothing was changed'),
    updated,
    aweme_id: awemeId,
  })
  if (publishTime != null) {
    const r = await post('/web/api/media/update/timer/?aid=1128', { aweme_id: awemeId, publish_time: publishTime })
    if (!r.ok) return fail(r)
    updated.push('reschedule')
  }
  if (caption) {
    const r = await post('/web/api/media/update/desc/?aid=1128', { aweme_id: awemeId, desc: caption })
    if (!r.ok) return fail(r)
    updated.push('caption')
  }
  return { ok: true, status: 'updated', aweme_id: awemeId, updated, publish_time: publishTime }
}

async function(args) {
  args = args || {}
  const API = 'https://api.juejin.cn'
  const title = String(args.title || '').trim()
  const markdown = String(args.markdown || '')
  if (!title) return { error: 'Missing argument: title' }
  if (!markdown.trim()) return { error: 'Missing argument: markdown' }
  const draftOnly = /^(1|true|yes|y|on)$/i.test(String(args.draft || ''))
  const tagNames = String(args.tags || '').split(/[,，]/).map((s) => s.trim()).filter(Boolean)

  // One request. The API answers {err_no, err_msg, data}; err_no 0 is success.
  // `body` null means GET.
  const call = async (path, body) => {
    let resp
    try {
      const url = API + path + (path.includes('?') ? '&' : '?') + 'aid=2608'
      resp = await fetch(url, body === null
        ? { credentials: 'include' }
        : {
            method: 'POST',
            credentials: 'include',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify(body || {}),
          })
    } catch (e) {
      return { ok: false, error: 'Network error calling ' + path + ': ' + (e && e.message) }
    }
    let j = null
    try { j = await resp.json() } catch (e) { j = null }
    if (!resp.ok || !j) return { ok: false, status: resp.status, error: 'HTTP ' + resp.status + ' from ' + path }
    if (j.err_no !== 0) return { ok: false, code: j.err_no, error: path + ': ' + (j.err_msg || 'err_no ' + j.err_no) }
    return { ok: true, data: j.data }
  }

  const me = await call('/user_api/v1/user/get', null)
  if (!me.ok || !me.data || !me.data.user_id) {
    return { error: 'Not signed in to juejin.cn', hint: 'Log in at https://juejin.cn in this browser, then retry.' }
  }

  // Category: accept a name (as the editor shows it) or a raw id.
  let categoryId = ''
  const catArg = String(args.category || '').trim()
  if (catArg) {
    if (/^\d{10,}$/.test(catArg)) {
      categoryId = catArg
    } else {
      const cats = await call('/tag_api/v1/query_category_list', {})
      if (!cats.ok) return { error: cats.error }
      const hit = (cats.data || []).find((c) => c.category && c.category.category_name === catArg)
      if (!hit) {
        return {
          error: 'Unknown Juejin category: ' + catArg,
          hint: 'Use one of: ' + (cats.data || []).map((c) => c.category && c.category.category_name).join(' '),
        }
      }
      categoryId = hit.category_id
    }
  }

  // Tags: exact (case-insensitive) matches only, so a typo never tags the
  // article with some unrelated neighbour from the search results.
  const tagIds = []
  const usedTags = []
  const skippedTags = []
  const found = await Promise.all(tagNames.map((name) =>
    call('/tag_api/v1/query_tag_list', { cursor: '0', key_word: name, limit: 10, sort_type: 1 })))
  tagNames.forEach((name, i) => {
    const rows = (found[i].ok && found[i].data) || []
    const hit = rows.find((t) => t.tag && t.tag.tag_name === name) ||
      rows.find((t) => t.tag && String(t.tag.tag_name).toLowerCase() === name.toLowerCase())
    if (hit && tagIds.length < 3 && !tagIds.includes(hit.tag_id)) {
      tagIds.push(hit.tag_id)
      usedTags.push(hit.tag.tag_name)
    } else {
      skippedTags.push(name)
    }
  })

  if (!draftOnly) {
    if (!categoryId) return { error: 'Publishing needs --category', hint: 'e.g. --category 人工智能, or pass --draft true' }
    if (!tagIds.length) return { error: 'None of the tags exist on Juejin: ' + tagNames.join(', '), hint: 'Publishing needs at least one existing tag.' }
  }

  // brief_content: Juejin rejects a publish outside 50-100 characters.
  let brief = String(args.summary || '').trim()
  if (!brief) {
    brief = markdown
      .replace(/```[\s\S]*?```/g, ' ')
      .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
      .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
      .replace(/[#>*_`~|-]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
  }
  brief = Array.from(brief).slice(0, 100).join('')

  const created = await call('/content_api/v1/article_draft/create', {
    category_id: categoryId || '0',
    tag_ids: tagIds,
    link_url: '',
    cover_image: '',
    title,
    brief_content: brief,
    edit_type: 10,
    html_content: 'deprecated',
    mark_content: markdown,
    theme_ids: [],
  })
  if (!created.ok) return { error: 'Could not create the draft: ' + created.error }
  const draftId = created.data && (created.data.id || created.data.draft_id)
  if (!draftId) return { error: 'Juejin created no draft id', hint: 'The draft API answer changed shape.' }
  const draftUrl = 'https://juejin.cn/editor/drafts/' + draftId
  const base = { id: String(draftId), draft_id: String(draftId), tags: usedTags, skipped_tags: skippedTags }

  if (draftOnly) return Object.assign({ ok: true, url: draftUrl, status: 'draft' }, base)

  const pub = await call('/content_api/v1/article/publish', {
    draft_id: String(draftId),
    sync_to_org: false,
    column_ids: [],
    theme_ids: [],
  })
  if (!pub.ok) {
    return Object.assign({
      error: 'Draft saved but publish failed: ' + pub.error,
      hint: 'Finish it by hand at ' + draftUrl + '. Do not re-run: that would create a second draft.',
      url: draftUrl,
      status: 'draft',
    }, base)
  }
  const articleId = String((pub.data && pub.data.article_id) || '')
  return Object.assign(base, {
    ok: true,
    id: articleId || String(draftId),
    url: articleId ? 'https://juejin.cn/post/' + articleId : draftUrl,
    // New posts go through Juejin's review before they are public.
    status: 'published',
  })
}

async function (args) {
  const repo = (args.repo || 'ka-cn/super-admin').replace(/^\/+|\/+$/g, '');
  if (!args.base) return { error: 'Missing argument: base', hint: 'dev | feature-test | main' };
  if (!args.head) return { error: 'Missing argument: head' };
  if (!args.title) return { error: 'Missing argument: title' };
  if (args.base === args.head)
    return { error: 'base and head are the same branch (' + args.base + ')', hint: 'Gogs would create an empty PR — refusing.' };

  const origin = location.origin; // https://sg-git.pwtk.cc
  const comparePath = '/' + repo + '/compare/' + args.base + '...' + args.head;
  const compareUrl = origin + comparePath;

  const getCsrf = (html) => {
    let m = html.match(/name="_csrf"[^>]*\bvalue="([^"]+)"/i);
    if (m) return m[1];
    m = html.match(/\bvalue="([^"]+)"[^>]*name="_csrf"/i);
    return m ? m[1] : null;
  };

  // 1) CSRF token — Gogs csrf is session-global, so grab it from the light repo home
  //    page instead of downloading a potentially huge compare diff.
  const homeResp = await fetch(origin + '/' + repo, { credentials: 'include', headers: { Accept: 'text/html' } });
  if (homeResp.status === 401 || homeResp.status === 403)
    return { error: 'HTTP ' + homeResp.status, hint: 'Not logged in to Gogs (or WARP not connected)' };
  if (homeResp.status === 404) return { error: 'Repo not found: ' + repo };
  const csrf = getCsrf(await homeResp.text());
  if (!csrf) return { error: 'CSRF token not found', hint: 'Not logged in to Gogs?' };

  // 2) POST the compare form exactly like the "Create Pull Request" button.
  const body = new URLSearchParams();
  body.set('_csrf', csrf);
  body.set('title', args.title);
  body.set('content', args.body || '');
  body.set('label_ids', '');
  body.set('milestone_id', '0');
  body.set('assignee_id', '0');

  const resp = await fetch(compareUrl, {
    method: 'POST',
    credentials: 'include',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Referer: compareUrl },
    body: body.toString(),
    redirect: 'follow'
  });

  const finalUrl = resp.url || '';
  const prMatch = finalUrl.match(/\/pulls\/(\d+)/);
  if (prMatch) {
    return { ok: true, number: Number(prMatch[1]), url: finalUrl, repo, base: args.base, head: args.head, title: args.title };
  }

  // Failure: Gogs re-rendered the compare page. Surface the most useful reason.
  const text = await resp.text();
  if (/branches are equal|has no changes|nothing to compare/i.test(text))
    return { error: 'No changes between branches', hint: '"' + args.head + '" has no commits ahead of "' + args.base + '"' };
  if (/pull request .*already exists|已经存在/i.test(text))
    return { error: 'A pull request for these branches already exists', url: finalUrl };
  const em = (text.match(/class="ui[^"]*negative[^"]*message"[^>]*>([\s\S]*?)<\/div>/i) || [])[1];
  return {
    error: 'PR not created (still on compare page)',
    status: resp.status,
    detail: em ? em.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 200) : undefined,
    url: finalUrl
  };
}

async function (args) {
  const repo = (args.repo || 'ka-cn/super-admin').replace(/^\/+|\/+$/g, '');
  const status = (args.status || args.state || 'open').toLowerCase();
  // Gogs' pulls page only accepts state=open|closed; expand "all" to both.
  const states = status === 'all' ? ['open', 'closed'] : [status];

  const seen = new Set();
  const prs = [];
  for (const st of states) {
    const url = location.origin + '/' + repo + '/pulls?state=' + encodeURIComponent(st);
    const r = await fetch(url, { credentials: 'include', headers: { Accept: 'text/html' } });
    if (r.status === 404) return { error: 'Repo not found: ' + repo };
    if (r.status === 401 || r.status === 403) return { error: 'HTTP ' + r.status, hint: 'Not logged in to Gogs (or WARP not connected)' };
    const doc = new DOMParser().parseFromString(await r.text(), 'text/html');
    doc.querySelectorAll('a[href*="/pulls/"]').forEach((a) => {
      const m = a.getAttribute('href').match(/\/pulls\/(\d+)(?:$|[?#])/);
      if (!m) return;
      const num = Number(m[1]);
      const title = (a.textContent || '').trim();
      if (!title || seen.has(num)) return;
      seen.add(num);
      prs.push({ number: num, title, state: st, url: location.origin + a.getAttribute('href').split(/[?#]/)[0] });
    });
  }

  prs.sort((a, b) => b.number - a.number);
  return { repo, status, count: prs.length, pulls: prs };
}

async function (args) {
  const repo = (args.repo || 'ka-cn/super-admin').replace(/^\/+|\/+$/g, '');
  const idx = String(args.pr != null ? args.pr : (args.number != null ? args.number : '')).replace(/^#/, '').trim();
  if (!/^\d+$/.test(idx)) return { error: 'Missing/invalid argument: pr', hint: 'PR number, e.g. --pr 134 (or positional: site sggit/pr-merge 134)' };
  const style = args.style || 'create_merge_commit';

  const origin = location.origin; // https://sg-git.pwtk.cc
  const prUrl = origin + '/' + repo + '/pulls/' + idx;

  const g = await fetch(prUrl, { credentials: 'include', headers: { Accept: 'text/html' } });
  if (g.status === 404) return { error: 'PR not found: ' + repo + '#' + idx };
  if (g.status === 401 || g.status === 403) return { error: 'HTTP ' + g.status, hint: 'Not logged in to Gogs (or WARP not connected)' };
  const html = await g.text();

  const mergeable = /can be merged automatically/i.test(html);
  const alreadyMerged = /has been merged|已被合并/i.test(html) && !mergeable;
  if (alreadyMerged) return { ok: true, already: true, merged: true, number: Number(idx), url: prUrl };
  if (/can't be merged automatically|cannot be merged|there are conflicts|存在冲突/i.test(html))
    return { error: 'PR has conflicts — cannot auto-merge', number: Number(idx), url: prUrl, hint: 'resolve conflicts manually' };
  if (!mergeable)
    return { error: 'No merge form available', number: Number(idx), url: prUrl, hint: 'PR may be closed/already merged, or you lack merge permission' };

  // csrf is session-global; any _csrf input on the page carries the same token.
  const csrf = (html.match(/name="_csrf"\s+value="([^"]+)"/i) || html.match(/name="_csrf"[^>]*\bvalue="([^"]+)"/i) || [])[1];
  if (!csrf) return { error: 'CSRF token not found', hint: 'Not logged in to Gogs?' };

  const body = new URLSearchParams();
  body.set('_csrf', csrf);
  body.set('merge_style', style);
  body.set('commit_description', args.message || '');

  const p = await fetch(prUrl + '/merge', {
    method: 'POST',
    credentials: 'include',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Referer: prUrl },
    body: body.toString(),
    redirect: 'follow'
  });

  // Verify the PR is now merged.
  const after = await (await fetch(prUrl, { credentials: 'include' })).text();
  if (/has been merged|已被合并/i.test(after) && !/can be merged automatically/i.test(after))
    return { ok: true, merged: true, number: Number(idx), url: prUrl, style };

  return { error: 'Merge did not complete (PR still not merged)', status: p.status, number: Number(idx), url: p.url || prUrl };
}

async function(args) {
  // The page encrypts both request and response bodies, so the adapter drives
  // the page's own Vue form instead of calling the API. Max span per query is
  // 3 years, and each query asks which 参保地 (one per provincial pool) to show.
  const QUERY_URL = 'https://si.12333.gov.cn/osptb/index.html#/protectCaptureQuery?2KZzg/x4yC1GtuDNv4vsJRwbmqWn7CuZL2iSBqV/vDE=';
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const visible = (el) => !!el && el.offsetParent !== null;
  const text = (el) => (el && el.innerText || '').replace(/\s+/g, ' ').trim();
  const progress = (m) => { if (typeof args.progress === 'function') args.progress(m); };

  const thisYear = new Date().getFullYear();
  const from = parseInt(args.from || '1995', 10);
  const to = parseInt(args.to || String(thisYear), 10);
  if (!(from > 1900 && to >= from)) return { error: 'bad year range', from: args.from, to: args.to };

  const modals = () => [...document.querySelectorAll('.ant-modal-wrap, .ant-modal')].filter(visible);
  const modalText = () => modals().map(text).join(' | ');
  const loggedOut = () => /登录信息已失效|请先登录/.test(modalText());
  const dismissNotices = async () => {
    for (let i = 0; i < 5; i++) {
      const b = [...document.querySelectorAll('.ant-modal button')].find((x) => visible(x) && text(x) === '知道了');
      if (!b) return;
      b.click();
      await sleep(250);
    }
  };
  const mainButton = () => [...document.querySelectorAll('button')]
    .find((x) => text(x).replace(/\s/g, '') === '查询' && !x.closest('.ant-modal'));

  if (!location.href.includes('protectCaptureQuery')) {
    location.href = QUERY_URL;
    return { status: 'incomplete', note: 'opened the query page' };
  }
  for (let i = 0; i < 40 && !mainButton(); i++) await sleep(250);
  if (loggedOut() || !mainButton()) {
    return { error: 'not logged in', hint: '在 si.12333.gov.cn 用掌上12333扫码或电子社保卡登录后重试' };
  }

  // Count completed payment queries; the page answers each with querySocialPayment.
  if (!window.__si12333Hook) {
    window.__si12333Hook = { done: 0 };
    const open = XMLHttpRequest.prototype.open;
    const send = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.open = function (m, u) { this.__siUrl = String(u); return open.apply(this, arguments); };
    XMLHttpRequest.prototype.send = function () {
      if (this.__siUrl && this.__siUrl.includes('querySocialPayment')) {
        this.addEventListener('loadend', () => { window.__si12333Hook.done++; });
      }
      return send.apply(this, arguments);
    };
  }

  const form = () => {
    let v = mainButton().__vue__;
    while (v && v.$options.name !== 'Form_WrappedComponent') v = v.$parent;
    return v;
  };
  const f = form();
  if (!f) return { error: 'query form not found; the page layout may have changed' };
  const shown = f.getFieldsValue();
  const proto = shown.aae042 || shown.aae041;
  if (!proto || !proto.clone) return { error: 'month picker value not found; click 重置 once and retry' };

  const readRows = () => {
    const out = [];
    document.querySelectorAll('.vxe-table--body .vxe-body--row, .ant-table-tbody tr').forEach((tr) => {
      const cells = [...tr.querySelectorAll('td')].map(text);
      if (cells.length >= 5 && /^\d{6}$/.test(cells[1])) {
        out.push({ period: cells[1], place: cells[2], employer: cells[3], personal: Number(cells[4]) });
      }
    });
    return out;
  };

  const waitQuery = async (before) => {
    for (let i = 0; i < 80; i++) {
      await sleep(150);
      if (window.__si12333Hook.done > before) { await sleep(600); return true; }
      if (loggedOut()) return false;
    }
    return false;
  };

  const queryWindow = async (y1, y2, region) => {
    await dismissNotices();
    f.setFieldsValue({
      aae041: proto.clone().year(y1).month(0).date(1),
      aae042: proto.clone().year(y2).month(11).date(1),
    });
    await sleep(200);
    const before = window.__si12333Hook.done;
    mainButton().click();
    let picker;
    for (let i = 0; i < 40; i++) {
      await sleep(150);
      picker = modals().find((m) => text(m).includes('请选择参保地'));
      if (picker || window.__si12333Hook.done > before || loggedOut()) break;
    }
    if (loggedOut()) throw new Error('logged out');
    if (!picker) {
      // A single pool answers directly without the chooser.
      await waitQuery(before);
      const notice = modalText();
      await dismissNotices();
      return { regions: [], rows: readRows(), notice };
    }
    const wrappers = [...picker.querySelectorAll('.ant-radio-wrapper')];
    const regions = wrappers.map(text);
    if (!region) return { regions };
    const w = wrappers.find((x) => text(x) === region);
    if (!w) throw new Error('region not offered: ' + region);
    (w.querySelector('input') || w).click();
    await sleep(200);
    const ok = [...picker.querySelectorAll('button')].find((x) => text(x).replace(/\s/g, '') === '查询');
    const before2 = window.__si12333Hook.done;
    ok.click();
    if (!(await waitQuery(before2))) {
      if (loggedOut()) throw new Error('logged out');
      throw new Error('query timed out: ' + region + ' ' + y1 + '-' + y2);
    }
    const notice = modalText();
    const rows = /未查询到/.test(notice) ? [] : readRows();
    await dismissNotices();
    return { rows, notice };
  };

  const windows = [];
  for (let y = from; y <= to; y += 3) windows.push([y, Math.min(y + 2, to)]);

  let regions;
  try {
    regions = (await queryWindow(windows[windows.length - 1][0], windows[windows.length - 1][1], null)).regions;
    const cancel = modals().map((m) => [...m.querySelectorAll('button')].find((x) => text(x).replace(/\s/g, '') === '返回')).find(Boolean);
    if (cancel) { cancel.click(); await sleep(300); }
  } catch (e) {
    return { error: String(e.message || e) };
  }
  if (!regions || !regions.length) regions = [null];
  if (args.region) regions = regions.filter((r) => r && r.includes(args.region));

  const rows = [];
  for (const region of regions) {
    for (const [y1, y2] of windows) {
      progress((region || '默认参保地') + ' ' + y1 + '-' + y2);
      try {
        const r = await queryWindow(y1, y2, region);
        for (const row of r.rows || []) {
          if (row.period.slice(0, 4) >= String(y1) && row.period.slice(0, 4) <= String(y2)) rows.push({ pool: region, ...row });
        }
      } catch (e) {
        return { error: String(e.message || e), partial: rows.length, rows };
      }
    }
  }

  const seen = new Set();
  const unique = rows.filter((r) => {
    const k = [r.pool, r.period, r.employer, r.personal].join('|');
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  }).sort((a, b) => a.period.localeCompare(b.period));

  const byMonth = {};
  unique.forEach((r) => { (byMonth[r.period] = byMonth[r.period] || []).push(r.pool); });
  const summary = {};
  unique.forEach((r) => {
    const s = summary[r.pool || ''] = summary[r.pool || ''] || { months: 0, first: r.period, last: r.period, personal_total: 0 };
    s.months++;
    s.last = r.period;
    s.personal_total = Math.round((s.personal_total + r.personal) * 100) / 100;
  });

  return {
    from, to,
    pools: regions.filter(Boolean),
    distinct_months: Object.keys(byMonth).length,
    overlapping_months: Object.keys(byMonth).filter((k) => new Set(byMonth[k]).size > 1),
    summary,
    rows: unique.map((r) => ({ ...r, base_est: Math.round(r.personal / 0.08) })),
  };
}

async function(args) {
  args = args || {}
  const W = window
  const D = document
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
  const isTwitterHost = (h) => h === 'x.com' || h === 'twitter.com' || h.endsWith('.x.com') || h.endsWith('.twitter.com')
  const statusPath = /^\/(?:[^/]+|i)\/status\/(\d+)\/?$/

  // The tweet id: a bare id, or the id in an https x.com/twitter.com status URL.
  const raw = String(args.tweet == null ? '' : args.tweet).trim()
  if (!raw) return { error: 'Missing argument: tweet', hint: 'Pass the tweet URL or id, e.g. chrome-use site twitter/delete https://x.com/you/status/123 --until-done' }
  let tweetId = null
  if (/^\d+$/.test(raw)) {
    tweetId = raw
  } else {
    let u = null
    try { u = new URL(raw) } catch (e) { u = null }
    if (!u || u.protocol !== 'https:' || !isTwitterHost(u.hostname.toLowerCase())) {
      return { error: 'Not an x.com tweet URL: ' + raw, hint: 'Use https://x.com/<user>/status/<id> or the numeric id' }
    }
    const m = u.pathname.match(statusPath)
    if (!m) return { error: 'No tweet id in ' + raw, hint: 'Use https://x.com/<user>/status/<id> or the numeric id' }
    tweetId = m[1]
  }

  // Open the tweet's own page first: the navigation ends this run, and
  // --until-done reruns the command there.
  const here = String(W.location.pathname || '').match(statusPath)
  if (!here || here[1] !== tweetId) {
    const url = 'https://x.com/i/status/' + tweetId
    setTimeout(() => W.location.assign(url), 800)
    return { status: 'navigating', url, retryAfterMs: 4000, hint: 'Opening the tweet; run the same command again there, or pass --until-done' }
  }

  const visible = (el) => !!el && (el.offsetParent !== null || (el.getClientRects && el.getClientRects().length > 0))
  const statusIdOf = (href) => {
    try {
      const u = new URL(href, W.location.origin)
      if (u.protocol !== 'https:' || !isTwitterHost(u.hostname.toLowerCase())) return null
      const m = u.pathname.match(statusPath)
      return m ? m[1] : null
    } catch (e) {
      return null
    }
  }
  // The <article> whose own status link is this tweet (a quoted or replied-to
  // tweet on the page has a different id).
  const findTargetArticle = () => Array.from(D.querySelectorAll('article'))
    .find((a) => Array.from(a.querySelectorAll('a[href*="/status/"]')).some((link) => statusIdOf(link.href || link.getAttribute('href')) === tweetId))

  // The article's self-link can hydrate late on a slow network.
  let article = findTargetArticle()
  for (let i = 0; i < 40 && !article; i += 1) {
    await sleep(250)
    article = findTargetArticle()
  }
  if (!article) return { error: 'tweet_not_found', id: tweetId, hint: 'The tweet did not show on its page (deleted already, or not visible to this account). Nothing changed' }

  const own = (el) => el.closest('article') === article
  // X localizes the ⋯ label (zh-Hans: 更多); prefer the data-testid.
  const moreMenu = Array.from(article.querySelectorAll('[data-testid="caret"]')).filter(own).find(visible)
    || Array.from(article.querySelectorAll('button,[role="button"]')).filter(own)
      .find((el) => visible(el) && /^(More|更多)/.test(String(el.getAttribute('aria-label') || '').trim()))
  if (!moreMenu) return { error: 'menu_not_found', id: tweetId, hint: 'The tweet has no ⋯ menu here; check that x.com is signed in. Nothing changed' }

  const before = new Set(Array.from(D.querySelectorAll('[role="menuitem"]')))
  moreMenu.click()
  await sleep(1000)
  const items = Array.from(D.querySelectorAll('[role="menuitem"]')).filter((item) => visible(item) && !before.has(item))
  // Delete / 删除, but never the "Add/remove from Lists" row.
  const deleteItem = items.find((item) => {
    const text = String(item.textContent || '').trim()
    return (text.includes('Delete') || text.includes('删除')) && !text.includes('List') && !text.includes('列表')
  })
  if (!deleteItem) return { error: 'not_own_tweet', id: tweetId, hint: 'The tweet menu has no Delete, so it is not this account\'s tweet. Nothing changed' }
  deleteItem.click()
  await sleep(1000)

  const confirm = D.querySelector('[data-testid="confirmationSheetConfirm"]')
  if (!confirm) return { error: 'confirm_not_shown', id: tweetId, hint: 'The delete confirmation did not appear; nothing was confirmed' }
  // Report at once: X may leave the tweet's page after a delete, which would
  // end this run before it could answer.
  confirm.click()
  return { ok: true, status: 'deleted', id: tweetId }
}

async function(args) {
  if (!args.query) return {error: 'Missing argument: query', hint: 'Provide a search query'};
