  }

  return {query: args.query, product, count: tweets.length, tweets};
}

async function(args) {
  if (!args.tweet_id) return {error: 'Missing argument: tweet_id', hint: 'Provide a tweet ID or URL'};
  const ct0 = document.cookie.split(';').map(c=>c.trim()).find(c=>c.startsWith('ct0='))?.split('=')[1];
  if (!ct0) return {error: 'No ct0 cookie', hint: 'Not logged into x.com'};
  const bearer = decodeURIComponent('AAAAAAAAAAAAAAAAAAAAANRILgAAAAAAnNwIzUejRCOuH5E6I8xnZz4puTs%3D1Zv7ttfk8LF81IUq16cHjhLTvJu4FA33AGWWjCpTnA');
  const _h = {'Authorization':'Bearer '+bearer, 'X-Csrf-Token':ct0, 'X-Twitter-Auth-Type':'OAuth2Session', 'X-Twitter-Active-User':'yes'};

  let tweetId = args.tweet_id;
  const urlMatch = tweetId.match(/\/status\/(\d+)/);
  if (urlMatch) tweetId = urlMatch[1];

  const features = JSON.stringify({
    responsive_web_graphql_exclude_directive_enabled: true, verified_phone_label_enabled: false,
    creator_subscriptions_tweet_preview_api_enabled: true, responsive_web_graphql_timeline_navigation_enabled: true,
    responsive_web_graphql_skip_user_profile_image_extensions_enabled: false,
    longform_notetweets_consumption_enabled: true, longform_notetweets_rich_text_read_enabled: true,
    longform_notetweets_inline_media_enabled: true, freedom_of_speech_not_reach_fetch_enabled: true
  });
  const fieldToggles = JSON.stringify({withArticleRichContentState: true, withArticlePlainText: false});
  const tweetDetailQueryId = findGraphQLQueryId('TweetDetail', 'nBS-WpgA6ZG0CyNHD517JQ');
  if (!tweetDetailQueryId) {
    return {error: 'Cannot find TweetDetail queryId', hint: 'x.com API structure may have changed'};
  }

  let tweets = [], seen = new Set(), cursor = null, maxPages = 5;

  function extractTweet(r) {
    if (!r) return;
    const tw = r.tweet || r; const l = tw.legacy || {};
    if (!tw.rest_id || seen.has(tw.rest_id)) return;
    seen.add(tw.rest_id);
    const u = tw.core?.user_results?.result;
    const nt = tw.note_tweet?.note_tweet_results?.result?.text;
    const screenName = u?.legacy?.screen_name || u?.core?.screen_name;
    const rawViewCount = tw.views?.count;
    const viewCount = rawViewCount == null ? null : Number(rawViewCount);
    tweets.push({id: tw.rest_id, author: screenName, text: nt || l.full_text || '',
      url: 'https://x.com/' + (screenName || '_') + '/status/' + tw.rest_id,
      likes: l.favorite_count ?? null, retweets: l.retweet_count ?? null,
      replies: l.reply_count ?? null, bookmarks: l.bookmark_count ?? null,
      views: Number.isFinite(viewCount) ? viewCount : null,
      in_reply_to: l.in_reply_to_status_id_str, created_at: l.created_at});
  }

  for (let page = 0; page < maxPages; page++) {
    const vars = {
      focalTweetId: tweetId, referrer: 'tweet', with_rux_injections: false,
      includePromotedContent: false, rankingMode: 'Recency',
      withCommunity: true, withQuickPromoteEligibilityTweetFields: true,
      withBirdwatchNotes: true, withVoice: true
    };
    if (cursor) vars.cursor = cursor;

    const url = '/i/api/graphql/' + tweetDetailQueryId + '/TweetDetail?variables=' + encodeURIComponent(JSON.stringify(vars)) + '&features=' + encodeURIComponent(features) + '&fieldToggles=' + encodeURIComponent(fieldToggles);
    const resp = await fetch(url, {headers: _h, credentials: 'include'});
    if (!resp.ok) return {error: 'HTTP ' + resp.status, hint: 'Tweet may not exist or queryId expired'};
    const d = await resp.json();

    const instructions = d.data?.threaded_conversation_with_injections_v2?.instructions || d.data?.tweetResult?.result?.timeline?.instructions || [];
    let nextCursor = null;

    for (const inst of instructions) {
      for (const entry of (inst.entries || [])) {
        if (entry.content?.entryType === 'TimelineTimelineCursor' || entry.content?.__typename === 'TimelineTimelineCursor') {
          if (entry.content.cursorType === 'Bottom' || entry.content.cursorType === 'ShowMore') {
            nextCursor = entry.content.value;
          }
          continue;
        }
        if (entry.entryId?.startsWith('cursor-bottom-') || entry.entryId?.startsWith('cursor-showMore-')) {
          const cv = entry.content?.itemContent?.value || entry.content?.value;
          if (cv) nextCursor = cv;
          continue;
        }

        extractTweet(entry.content?.itemContent?.tweet_results?.result);
        for (const item of (entry.content?.items || [])) {
          extractTweet(item.item?.itemContent?.tweet_results?.result);
        }
      }
    }

    if (!nextCursor || nextCursor === cursor) break;
    cursor = nextCursor;
  }

  return {tweet_id: tweetId, count: tweets.length, tweets};
}

async function(args) {
  args = args || {};
  const ct0 = document.cookie.split(';').map(c=>c.trim()).find(c=>c.startsWith('ct0='))?.split('=')[1];
  if (!ct0) return {error: 'No ct0 cookie', hint: 'Not logged into x.com. Open x.com and log in first.'};
  const bearer = decodeURIComponent('AAAAAAAAAAAAAAAAAAAAANRILgAAAAAAnNwIzUejRCOuH5E6I8xnZz4puTs%3D1Zv7ttfk8LF81IUq16cHjhLTvJu4FA33AGWWjCpTnA');
  const _h = {'Authorization':'Bearer '+bearer, 'X-Csrf-Token':ct0, 'X-Twitter-Auth-Type':'OAuth2Session', 'X-Twitter-Active-User':'yes'};

  let screenName = String(args.screen_name || '').trim().replace(/^@/, '');
  const urlMatch = screenName.match(/(?:x|twitter)\.com\/([A-Za-z0-9_]+)/);
  if (urlMatch) screenName = urlMatch[1];
  if (!screenName) {
    // The side nav's Profile link carries the signed-in handle.
    const link = document.querySelector('[data-testid="AppTabBar_Profile_Link"]');
    const m = link && (link.getAttribute('href') || '').match(/^\/([A-Za-z0-9_]+)/);
    if (!m) return {error: 'Cannot tell which account is signed in', hint: 'Pass a handle: chrome-use site twitter/user <screen_name>'};
    screenName = m[1];
  }

  const variables = JSON.stringify({screen_name: screenName, withSafetyModeUserFields: true});
  const features = JSON.stringify({
    hidden_profile_subscriptions_enabled: true, responsive_web_graphql_exclude_directive_enabled: true,
    verified_phone_label_enabled: false, responsive_web_graphql_skip_user_profile_image_extensions_enabled: false,
    responsive_web_graphql_timeline_navigation_enabled: true, profile_label_improvements_pcf_label_in_post_enabled: true,
    rweb_tipjar_consumption_enabled: true, subscriptions_feature_can_gift_premium: true,
    highlights_tweets_tab_ui_enabled: true, responsive_web_twitter_article_notes_tab_enabled: true,
    subscriptions_verification_info_is_identity_verified_enabled: true,
    subscriptions_verification_info_verified_since_enabled: true, creator_subscriptions_tweet_preview_api_enabled: true
  });
  const queryId = findGraphQLQueryId('UserByScreenName', 'pLsOiyHJ1eFwPJlNmLp4Bg');
  if (!queryId) return {error: 'Cannot find UserByScreenName queryId', hint: 'x.com API structure may have changed'};
  const url = '/i/api/graphql/' + queryId + '/UserByScreenName?variables=' + encodeURIComponent(variables) + '&features=' + encodeURIComponent(features);
  const resp = await fetch(url, {headers: _h, credentials: 'include'});
  if (!resp.ok) return {error: 'HTTP ' + resp.status, hint: 'queryId may have changed. Check network tab.'};
  const d = await resp.json();
  const u = d.data?.user?.result;
  if (!u || u.__typename === 'UserUnavailable') return {error: 'User not found', hint: 'Check spelling: @' + screenName};

  // X keeps moving profile fields out of `legacy`: name/screen_name/created_at
  // went to `core`, bio and location to their own objects, and with the 2026
  // query the counts to relationship_counts / tweet_counts / action_counts.
  // Read the new place first and fall back to legacy for older query ids.
  const l = u.legacy || {};
  const c = u.core || {};
  const rel = u.relationship_counts || {};
  const tc = u.tweet_counts || {};
  const ac = u.action_counts || {};
  const num = (...vs) => {
    for (const v of vs) if (v != null && v !== '' && Number.isFinite(Number(v))) return Number(v);
    return null;
  };
  const handle = c.screen_name || l.screen_name || screenName;
  return {
    id: u.rest_id || null,
    name: c.name || l.name || null,
    screen_name: handle,
    url: 'https://x.com/' + handle,
    bio: u.profile_bio?.description ?? l.description ?? null,
    location: u.location?.location ?? l.location ?? null,
    website: l.entities?.url?.urls?.[0]?.expanded_url || u.website?.url || l.url || null,
    created_at: c.created_at || l.created_at || null,
    followers: num(rel.followers, l.followers_count),
    following: num(rel.following, l.friends_count),
    tweets: num(tc.tweets, l.statuses_count),
    media: num(tc.media_tweets, l.media_count),
    likes: num(ac.favorites_count, l.favourites_count),
    pinned_tweet_ids: u.pinned_items?.tweet_ids_str || l.pinned_tweet_ids_str || [],
    verified: Boolean(u.is_blue_verified),
  };
}

async function(args) {
  args = args || {}
  const budget = xhscBudget()
  const ready = await xhscReady(budget)
  if (ready.error) return ready
  const { client, user } = ready
  const wantSummary = String(args.summary).toLowerCase() !== 'false'

  // personal_info is what the creator home page header renders. The user id is
  // not in it; the page's own Vuex store already holds it, so no extra call.
  // Both requests go out together, as they do when the home page loads.
  const [info, acct] = await Promise.all([
    xhscGet(client, '/api/galaxy/creator/home/personal_info', { transform: true }, budget),
    wantSummary
      ? xhscGet(client, '/api/galaxy/v2/creator/datacenter/account/base', { transform: true }, budget)
      : null,
  ])
  if (!info.ok) return { error: info.error, hint: info.hint, status: info.status }
  const p = info.data || {}

  const out = {
    user_id: user.userId,
    nickname: p.name || user.userName || null,
    red_id: p.redNum || user.redId || null,
    avatar: p.avatar || user.userAvatar || null,
    desc: p.personalDesc || null,
    fans: xhscNum(p.fansCount),
    follows: xhscNum(p.followCount),
    // 获赞与收藏: XHS only publishes the combined figure.
    likes_and_collects: xhscNum(p.favedCount),
    level: xhscNum(p.growInfo && p.growInfo.level),
    profile_url: 'https://www.xiaohongshu.com/user/profile/' + user.userId,
    data_center: null,
  }

  if (!acct) return out
  if (!acct.ok) {
    // The profile half is still good; say why the summary is missing.
    out.data_center = { error: acct.error, hint: acct.hint || null }
    return out
  }
  const period = (d) => {
    if (!d || typeof d !== 'object') return null
    return {
      start: xhscDateFromMs(d.beginTime),
      end: xhscDateFromMs(d.endTime),
      impressions: xhscNum(d.implCount),
      views: xhscNum(d.viewCount),
      cover_click_rate_pct: xhscNum(d.coverClickRate),
      avg_view_time_sec: xhscNum(d.avgViewTime != null ? d.avgViewTime : d.viewTimeAvg),
      home_views: xhscNum(d.homeViewCount),
      likes: xhscNum(d.likeCount),
      collects: xhscNum(d.collectCount),
      comments: xhscNum(d.commentCount),
      shares: xhscNum(d.shareCount),
      new_fans: xhscNum(d.riseFansCount),
      lost_fans: xhscNum(d.lossFansCount),
      net_new_fans: xhscNum(d.netRiseFansCount),
      notes_published: xhscNum(d.publishNoteNum),
    }
  }
  out.data_center = {
    last_7_days: period(acct.data && acct.data.seven),
    last_30_days: period(acct.data && acct.data.thirty),
  }
  return out
}

async function(args) {
  args = args || {}
  const noteId = xhscParseNoteId(args.note_id)
  if (!noteId) {
    return {
      error: 'Missing or invalid note_id: ' + (args.note_id == null ? '' : args.note_id),
      hint: 'Pass a 24-hex note id or a https://www.xiaohongshu.com/explore/<id> URL.',
    }
  }

  const budget = xhscBudget()
  const ready = await xhscReady(budget)
  if (ready.error) return ready
  const { client } = ready
  const opts = { params: { note_id: noteId }, transform: true }
  const wantAudience = String(args.audience).toLowerCase() !== 'false'

  // The same calls the 笔记数据 detail page makes on open, sent together as it
  // sends them.
  const [base, src, det] = await Promise.all([
    xhscGet(client, '/api/galaxy/creator/datacenter/note/base', opts, budget),
    wantAudience ? xhscGet(client, '/api/galaxy/creator/datacenter/note/audience/source', opts, budget) : null,
    wantAudience ? xhscGet(client, '/api/galaxy/creator/datacenter/note/audience/source/detail', opts, budget) : null,
  ])
  if (!base.ok) return { error: base.error, hint: base.hint, status: base.status, note_id: noteId }
  const b = base.data || {}
  const info = b.noteInfo || {}
  if (!info.id) {
    return {
      error: 'No data-center record for note ' + noteId,
      hint: 'note-stats only covers notes published by the signed-in account.',
      note_id: noteId,
    }
  }
  const isVideo = String(info.type || '').toUpperCase() === 'VIDEO'

  const out = {
    note_id: info.id,
    type: isVideo ? 'video' : 'normal',
    desc: info.desc || null,
    published_at: xhscIsoFromMs(info.postTime),
    days_since_post: xhscNum(b.notePostDays),
    // When the data center last rolled up this note's numbers. Absent for
    // notes still inside the first day, when most rates read -1 (→ null).
    data_updated_at: xhscIsoFromMs(b.basicDataLastUpdateTime),
    cover: info.coverUrl || null,
    url: 'https://www.xiaohongshu.com/explore/' + info.id,
    topics: Array.isArray(info.tags) ? info.tags.map((t) => t && t.name).filter(Boolean) : [],
    metrics: {
      impressions: xhscNum(b.implCount),
      views: xhscNum(b.viewCount),
      cover_click_rate_pct: xhscNum(b.coverClickRate),
      avg_view_time_sec: xhscNum(b.viewTimeAvg),
      likes: xhscNum(b.likeCount),
      collects: xhscNum(b.collectCount),
      comments: xhscNum(b.commentCount),
      shares: xhscNum(b.shareCount),
      follows_gained: xhscNum(b.riseFansCount),
      danmaku: xhscNum(b.danmakuCount),
      interaction_rate_pct: xhscNum(b.interactionRate),
      // 图文 only: how many images a viewer swipes through on average.
      avg_images_viewed: isVideo ? null : xhscNum(b.avgViewImage),
      // Video only. Image notes report 0 for these, which means "n/a", not 0%.
      full_view_rate_pct: isVideo ? xhscNum(b.fullViewRate) : null,
      finish_5s_rate_pct: isVideo ? xhscNum(b.finish5sRate) : null,
      exit_2s_rate_pct: isVideo ? xhscNum(b.exitView2sRate) : null,
      play_60s_count: isVideo ? xhscNum(b.play60sCount) : null,
    },
    traffic_sources: null,
    audience: null,
  }

  if (!wantAudience) return out

  // Each item is {title, value, valueWithDouble}; valueWithDouble is the
  // percentage the page draws (value is sometimes a rounded copy).
  const shares = (list) =>
    Array.isArray(list)
      ? list.map((x) => ({
          name: (x && (x.title || x.name)) || null,
          pct: xhscNum(x && (x.valueWithDouble != null ? x.valueWithDouble : x.value)),
        }))
      : []

  if (src.ok) {
    const s = src.data || {}
    out.traffic_sources = s.noData
      ? { available: false, reason: s.noDataTipMsg || null, sources: [] }
      : { available: true, reason: null, sources: shares(s.source) }
  } else {
    out.traffic_sources = { available: false, reason: src.error, sources: [] }
  }

  if (det.ok) {
    const d = det.data || {}
    out.audience = {
      available: !d.noData,
      reason: d.noData ? d.noDataTipMsg || null : null,
      gender: shares(d.gender),
      age: shares(d.age),
      city: shares(d.city),
      interest: shares(d.interest),
    }
  } else {
    out.audience = { available: false, reason: det.error, gender: [], age: [], city: [], interest: [] }
  }
  return out
}

async function(args) {
  args = args || {}
  // The note manager's tab ids. `tab_status` on a note uses a DIFFERENT
  // numbering (1 published, 2 reviewing, 3 rejected, 4 scheduled).
  const TABS = {
    all: 0, '全部': 0, '0': 0,
    published: 1, '已发布': 1, '1': 1,
    reviewing: 2, review: 2, '审核中': 2, '2': 2,
    rejected: 3, deny: 3, '未通过': 3, '3': 3,
    scheduled: 4, '定时发布': 4, '4': 4,
  }
  const STATUS = {
    1: ['published', '已发布'],
    2: ['reviewing', '审核中'],
    3: ['rejected', '未通过'],
    4: ['scheduled', '定时发布'],
  }
  const VISIBILITY = {
    0: ['public', '公开可见'],
    1: ['private', '仅自己可见'],
    2: ['partially_hidden', '部分人不可见'],
    3: ['partially_visible', '部分人可见'],
    4: ['friends_only', '仅互关好友可见'],
  }

  const tabKey = args.tab == null || args.tab === '' ? 'all' : String(args.tab).trim().toLowerCase()
  if (!(tabKey in TABS)) {
    return { error: 'Unknown tab: ' + args.tab, hint: 'Use all, published, reviewing, rejected or scheduled.' }
  }
  const tab = TABS[tabKey]
  const limit = xhscCount(args.limit, 20, 50)
  const startRaw = Number(args.page)
  let page = Number.isInteger(startRaw) && startRaw > 0 ? startRaw : 0

  const budget = xhscBudget()
  const ready = await xhscReady(budget)
  if (ready.error) return ready
  const { client } = ready

  // One request per server page of 10, capped by `limit`. This is the same
  // call the note manager makes as you scroll, and it stops at the first
  // short/last page instead of probing further.
  const raw = []
  let total = null
  let next = page
  let lastFetched = page
  let partial = null
  const maxPages = Math.ceil(limit / 10)
  for (let i = 0; i < maxPages && next !== -1 && raw.length < limit; i++) {
    lastFetched = next
    const res = await xhscGet(client, '/api/galaxy/v2/creator/note/user/posted', {
      params: { tab, page: next },
      withCredentials: true,
    }, budget)
    if (!res.ok) {
      if (!raw.length) return { error: res.error, hint: res.hint, status: res.status }
      // Out of time or failed on a later page: return what we have, with the
      // cursor pointing at the page that did not arrive.
      partial = res.error
      next = lastFetched
      break
    }
    const d = res.data || {}
    if (total === null && Array.isArray(d.tags) && d.tags[0]) total = xhscNum(d.tags[0].notes_count)
    const notes = Array.isArray(d.notes) ? d.notes : []
    raw.push(...notes)
    // The server returns the NEXT page number, or -1 once it has none left.
    next = typeof d.page === 'number' ? d.page : -1
    if (!notes.length) next = -1
  }

  // The cursor has page granularity. If `limit` cut the last page short, point
  // next_page back at that page: resuming repeats a few notes (dedupe by id)
  // rather than silently skipping the ones that were cut.
  if (raw.length > limit && !partial) next = lastFetched

  const notes = raw.slice(0, limit).map((n) => {
    const status = STATUS[n.tab_status] || [null, null]
    const vis = VISIBILITY[n.permission_code] || [null, null]
    const duration = n.video_info && xhscNum(n.video_info.duration)
    const isVideo = n.type === 'video' || !!duration
    // `time` is China-local "YYYY-MM-DD HH:mm"; give it an explicit offset.
    const tm = typeof n.time === 'string' && n.time.match(/^(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2})(?::(\d{2}))?$/)
    const images = Array.isArray(n.images_list) ? n.images_list : []
    return {
      id: n.id,
      title: n.display_title || null,
      type: isVideo ? 'video' : 'normal',
      published_at: tm ? tm[1] + 'T' + tm[2] + ':' + (tm[3] || '00') + '+08:00' : null,
      status: status[0],
      status_text: status[1],
      status_code: n.tab_status == null ? null : n.tab_status,
      visibility: vis[0],
      visibility_text: n.permission_msg || vis[1],
      visibility_code: n.permission_code == null ? null : n.permission_code,
      pinned: n.sticky === true,
      scheduled_at: n.schedule_post_time
        ? xhscIsoFromMs(n.schedule_post_time > 1e12 ? n.schedule_post_time : n.schedule_post_time * 1000)
        : null,
      video_duration: isVideo ? duration || null : null,
      cover: (images[0] && images[0].url) || null,
      url: xhscNoteUrl(n.id, n.xsec_token, n.xsec_source),
      xsec_token: n.xsec_token || null,
      views: xhscNum(n.view_count),
      likes: xhscNum(n.likes),
      collects: xhscNum(n.collected_count),
      comments: xhscNum(n.comments_count),
      shares: xhscNum(n.shared_count),
    }
  })

  return {
    tab: ['all', 'published', 'reviewing', 'rejected', 'scheduled'][tab],
    count: notes.length,
    // tags[0].notes_count: the figure the note manager shows next to the tab.
    total,
    page,
    // Pass back as --page to continue; null means there is nothing more.
    next_page: next === -1 ? null : next,
    // Set when a later page failed or ran out of time; `notes` is still valid.
    partial,
    notes,
  }
}

async function(args) {
  args = args || {}
  const wantNotes = Math.min(Math.max(parseInt(args.notes, 10) || 0, 0), 30)
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

  // Who is signed in: the page's own Pinia user store, as the web app has it.
  let info = null
  for (let i = 0; i < 20 && !info; i++) {
    const app = document.querySelector('#app') && document.querySelector('#app').__vue_app__
    const store = app && app.config && app.config.globalProperties.$pinia && app.config.globalProperties.$pinia._s.get('user')
    const u = store && store.userInfo
    if (u && (u.userId || u.user_id) && !u.guest) info = JSON.parse(JSON.stringify(u))
    else await sleep(250)
  }
  if (!info) return { error: 'Not logged in', hint: 'Open https://www.xiaohongshu.com and log in (QR code), then retry' }
  const userId = info.userId || info.user_id

  // The counts are only in the profile page's server-rendered state. One GET
  // of that page, the same request a visit to the profile makes; Xiaohongshu
  // bans accounts for scripted traffic, so no API calls and no paging.
  let html
  try {
    const resp = await fetch('/user/profile/' + userId, { credentials: 'include' })
    if (!resp.ok) return { error: 'HTTP ' + resp.status, hint: 'Open your profile page once in the browser, then retry' }
    html = await resp.text()
  } catch (e) {
    return { error: 'Network error: ' + (e && e.message || e) }
  }
  const m = html.match(/window\.__INITIAL_STATE__\s*=\s*(\{[\s\S]*?\})\s*<\/script>/)
  if (!m) return { error: 'Profile state not found', hint: 'Xiaohongshu may have changed its page; check the profile page source' }
  let state
  try {
    // The state is a JS literal, not JSON: undefined and new Set([...]) appear in it.
    state = JSON.parse(m[1].replace(/\bundefined\b/g, 'null').replace(/new (?:Set|Map)\(\[[^\]]*\]\)/g, '[]'))
  } catch (e) {
    return { error: 'Cannot parse profile state: ' + e.message }
  }
  const page = (state.user && state.user.userPageData) || {}
  const basic = page.basicInfo || {}
  const counts = {}
  for (const it of page.interactions || []) counts[it.type] = it.count
  const num = (v) => (v == null || v === '' || !Number.isFinite(Number(v)) ? null : Number(v))

  const out = {
    userid: userId,
    nickname: basic.nickname || info.nickname || null,
    red_id: basic.redId || info.redId || info.red_id || null,
    desc: basic.desc != null ? basic.desc : (info.desc || null),
    gender: basic.gender != null ? basic.gender : (info.gender != null ? info.gender : null),
    ip_location: basic.ipLocation || null,
    follows: num(counts.follows),
    fans: num(counts.fans),
    // 获赞与收藏: Xiaohongshu only shows the combined figure.
    likes_and_collects: num(counts.interaction),
    url: 'https://www.xiaohongshu.com/user/profile/' + userId,
  }
  if (wantNotes > 0) {
    const first = (state.user && Array.isArray(state.user.notes) && state.user.notes[0]) || []
    out.notes = first.slice(0, wantNotes).map((n) => {
      const card = n.noteCard || {}
      const id = card.noteId || n.id
      return {
        note_id: id,
        title: card.displayTitle || '',
        type: card.type || null,
        likes: num(card.interactInfo && card.interactInfo.likedCount),
        sticky: Boolean(card.interactInfo && card.interactInfo.sticky),
        url: 'https://www.xiaohongshu.com/explore/' + id + (n.xsecToken ? '?xsec_token=' + encodeURIComponent(n.xsecToken) + '&xsec_source=pc_user' : ''),
      }
    })
  }
  return out
}

async function(args) {
  args = args || {}
  const parsed = parseInt(args.limit, 10)
  const limit = Number.isFinite(parsed) ? Math.min(Math.max(parsed, 0), 500) : 30
  const cfg = (k) => (window.ytcfg && typeof window.ytcfg.get === 'function' ? window.ytcfg.get(k) : undefined)
  const channelId = cfg('CHANNEL_ID')
  const apiKey = cfg('INNERTUBE_API_KEY')
  if (!channelId || !apiKey) {
    return { error: 'Not on a signed-in YouTube Studio page', hint: 'Open https://studio.youtube.com and sign in, then retry' }
  }
  const sapisid = (document.cookie.match(/(?:^|;\s*)(?:SAPISID|__Secure-3PAPISID)=([^;]+)/) || [])[1]
  if (!sapisid) return { error: 'No SAPISID cookie', hint: 'Sign in to YouTube in this browser, then retry' }

  // Studio's own calls carry a SAPISIDHASH: sha1("<ts> <SAPISID> <origin>").
  const ts = Math.floor(Date.now() / 1000)
  const digest = await crypto.subtle.digest('SHA-1', new TextEncoder().encode(ts + ' ' + sapisid + ' ' + location.origin))
  const hash = Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('')
  const context = JSON.parse(JSON.stringify(cfg('INNERTUBE_CONTEXT') || {}))
  context.user = Object.assign({}, context.user, {
    delegationContext: { externalChannelId: channelId, roleType: { channelRoleType: 'CREATOR_CHANNEL_ROLE_TYPE_OWNER' } },
  })
  const headers = {
    'Content-Type': 'application/json',
    Authorization: 'SAPISIDHASH ' + ts + '_' + hash,
    'X-Goog-AuthUser': String(cfg('SESSION_INDEX') || 0),
    'X-Origin': location.origin,
    'X-YouTube-Client-Name': String(cfg('INNERTUBE_CONTEXT_CLIENT_NAME') || 62),
    'X-YouTube-Client-Version': String(cfg('INNERTUBE_CONTEXT_CLIENT_VERSION') || ''),
  }
  async function call(path, body) {
    let resp
    try {
      resp = await fetch('/youtubei/v1/' + path + '?alt=json&key=' + encodeURIComponent(apiKey), {
        method: 'POST', credentials: 'include', headers, body: JSON.stringify(Object.assign({ context }, body)),
      })
    } catch (e) {
      return { error: 'Network error: ' + (e && e.message || e) }
    }
    const d = await resp.json().catch(() => null)
    if (!resp.ok || !d || d.error) {
      return { error: 'HTTP ' + resp.status + (d && d.error && d.error.message ? ': ' + d.error.message : ''), status: resp.status }
    }
    return { d }
  }
  const num = (v) => (v == null || v === '' || !Number.isFinite(Number(v)) ? null : Number(v))

  const ch = await call('creator/get_creator_channels', {
    channelIds: [channelId],
    mask: { channelId: true, title: true, customUrl: true, metric: { all: true } },
  })
  if (ch.error) return { error: ch.error, hint: ch.status === 401 || ch.status === 403 ? 'Sign in to YouTube Studio again' : 'Studio API may have changed' }
  const c = (ch.d.channels || [])[0] || {}
  const m = c.metric || {}
  const out = {
    channel_id: channelId,
    title: c.title || null,
    custom_url: c.customUrl || null,
    url: 'https://www.youtube.com/channel/' + channelId,
    subscribers: num(m.subscriberCount),
    videos: num(m.videoCount),
    total_views: num(m.totalVideoViewCount),
  }
  if (limit === 0) return out

  const PRIVACY = { VIDEO_PRIVACY_PUBLIC: 'public', VIDEO_PRIVACY_UNLISTED: 'unlisted', VIDEO_PRIVACY_PRIVATE: 'private', VIDEO_PRIVACY_DRAFT: 'draft' }
  const uploads = []
  let pageToken = null
  let error = null
  for (let i = 0; i < 20 && uploads.length < limit; i++) {
    const body = {
      filter: { and: { operands: [{ channelIdIs: { value: channelId } }, { videoOriginIs: { value: 'VIDEO_ORIGIN_UPLOAD' } }] } },
      order: 'VIDEO_ORDER_DISPLAY_TIME_DESC',
      pageSize: Math.min(50, limit - uploads.length),
      mask: {
        videoId: true, title: true, privacy: true, contentType: true, lengthSeconds: true,
        timePublishedSeconds: true, timeCreatedSeconds: true, publicMetrics: { all: true }, status: true, draftStatus: true,
      },
    }
    if (pageToken) body.pageToken = pageToken
    const r = await call('creator/list_creator_videos', body)
    if (r.error) { error = r.error; break }
    for (const v of r.d.videos || []) {
      const pm = v.publicMetrics || {}
      const secs = num(v.timePublishedSeconds) || num(v.timeCreatedSeconds)
      uploads.push({
        video_id: v.videoId,
        title: v.title || '',
        type: v.contentType === 'CREATOR_CONTENT_TYPE_SHORTS' ? 'short' : 'video',
        visibility: v.draftStatus && v.draftStatus !== 'DRAFT_STATUS_NONE' ? 'draft' : (PRIVACY[v.privacy] || v.privacy || null),
        published_at: secs ? new Date(secs * 1000).toISOString() : null,
        duration_sec: num(v.lengthSeconds),
        views: num(pm.externalViewCount),
        likes: num(pm.likeCount),
        comments: num(pm.commentCount),
        url: v.contentType === 'CREATOR_CONTENT_TYPE_SHORTS' ? 'https://www.youtube.com/shorts/' + v.videoId : 'https://www.youtube.com/watch?v=' + v.videoId,
      })
    }
    pageToken = r.d.nextPageToken || null
    if (!pageToken) break
  }
  out.uploads = uploads.slice(0, limit)
  if (error) out.uploads_error = error
  return out
}

async function(args) {
  args = args || {}
  const title = String(args.title || '').trim()
  const markdown = String(args.markdown || '')
  if (!title) return { error: 'Missing argument: title' }
  if (!markdown.trim() && !args.html) return { error: 'Missing argument: markdown' }
  const draftOnly = /^(1|true|yes|y|on)$/i.test(String(args.draft || ''))
  const tagNames = String(args.tags || '').split(/[,，]/).map((s) => s.trim()).filter(Boolean)

  // ---- markdown → html (shared verbatim by csdn/ and zhihu/; a test keeps the copies equal)
  // Covers what blog posts use: headings, paragraphs, fenced code, block
  // quotes, flat or nested lists, rules, GFM tables, bold/italic/strike,
  // inline code, links, images. Raw HTML in the source is escaped, not passed.
  const mdToHtml = (src, codeBlock) => {
    const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
    const inline = (text) => {
      const slots = []
      const keep = (html) => '\u0000' + (slots.push(html) - 1) + '\u0000'
      let s = String(text).replace(/(`+)([^`]|[^`][\s\S]*?[^`])\1(?!`)/g, (m, t, c) => keep('<code>' + esc(c.trim()) + '</code>'))
      s = s.replace(/!\[([^\]]*)\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g, (m, alt, url) => keep('<img src="' + esc(url) + '" alt="' + esc(alt) + '">'))
      s = s.replace(/\[([^\]]+)\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g, (m, label, url) => keep('<a href="' + esc(url) + '">' + inline(label) + '</a>'))
      s = s.replace(/<(https?:\/\/[^\s>]+)>/g, (m, url) => keep('<a href="' + esc(url) + '">' + esc(url) + '</a>'))
      s = esc(s)
      s = s.replace(/\*\*(?=\S)([\s\S]*?\S)\*\*/g, '<strong>$1</strong>').replace(/__(?=\S)([\s\S]*?\S)__/g, '<strong>$1</strong>')
      s = s.replace(/~~(?=\S)([\s\S]*?\S)~~/g, '<del>$1</del>')
      s = s.replace(/(^|[^*\w])\*(?=\S)([^*]*?\S)\*(?!\*)/g, '$1<em>$2</em>')
      s = s.replace(/(^|[^_\w])_(?=\S)([^_]*?\S)_(?![_\w])/g, '$1<em>$2</em>')
      s = s.replace(/ {2,}\n/g, '<br>\n')
      return s.replace(/\u0000(\d+)\u0000/g, (m, i) => slots[Number(i)])
    }
    const cells = (row) => row.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim())
    const blocks = (lines) => {
      const out = []
      let i = 0
      const isFence = (l) => /^\s{0,3}(```|~~~)/.test(l)
      const isHr = (l) => /^\s{0,3}([-*_])(\s*\1){2,}\s*$/.test(l)
      const isHead = (l) => /^\s{0,3}#{1,6}(\s|$)/.test(l)
      const isQuote = (l) => /^\s{0,3}>/.test(l)
      const isItem = (l) => /^\s{0,3}([-*+]|\d{1,9}[.)])\s+/.test(l)
      const isTable = (k) => /\|/.test(lines[k] || '') && /^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)*\|?\s*$/.test(lines[k + 1] || '')
      while (i < lines.length) {
        const line = lines[i]
        if (!line.trim()) { i++; continue }
        if (isFence(line)) {
          const fence = line.trim().slice(0, 3)
          const lang = line.trim().slice(3).trim().split(/\s+/)[0] || ''
          const body = []
          i++
          while (i < lines.length && !lines[i].trim().startsWith(fence)) body.push(lines[i++])
          i++
          out.push(codeBlock(lang, esc(body.join('\n'))))
          continue
        }
        if (isHead(line)) {
          const m = line.trim().match(/^(#{1,6})\s*(.*?)\s*#*\s*$/)
          out.push('<h' + m[1].length + '>' + inline(m[2]) + '</h' + m[1].length + '>')
          i++
          continue
        }
        if (isHr(line)) { out.push('<hr>'); i++; continue }
        if (isQuote(line)) {
          const body = []
          while (i < lines.length && lines[i].trim() && isQuote(lines[i])) body.push(lines[i++].replace(/^\s{0,3}>\s?/, ''))
          out.push('<blockquote>' + blocks(body) + '</blockquote>')
          continue
        }
        if (isTable(i)) {
          const head = cells(lines[i])
          i += 2
          const rows = []
          while (i < lines.length && lines[i].trim() && /\|/.test(lines[i])) rows.push(cells(lines[i++]))
          out.push('<table><thead><tr>' + head.map((c) => '<th>' + inline(c) + '</th>').join('') + '</tr></thead><tbody>' +
            rows.map((r) => '<tr>' + r.map((c) => '<td>' + inline(c) + '</td>').join('') + '</tr>').join('') + '</tbody></table>')
          continue
        }
        if (isItem(line)) {
          const ordered = /^\s{0,3}\d/.test(line)
          const indent = line.match(/^\s*/)[0].length
          const items = []
          while (i < lines.length) {
            const l = lines[i]
            const ind = l.match(/^\s*/)[0].length
            if (isItem(l) && ind <= indent + 1) {
              if (/^\s{0,3}\d/.test(l) !== ordered) break
              items.push([l.replace(/^\s*([-*+]|\d{1,9}[.)])\s+/, '')])
              i++
            } else if (l.trim() && items.length && (ind > indent || !(isFence(l) || isHead(l) || isQuote(l) || isHr(l)))) {
              items[items.length - 1].push(ind > indent ? l.slice(Math.min(ind, indent + 2)) : l)
              i++
            } else if (!l.trim() && i + 1 < lines.length && lines[i + 1].match(/^\s*/)[0].length > indent && lines[i + 1].trim()) {
              items[items.length - 1].push('')
              i++
            } else break
          }
          const tag = ordered ? 'ol' : 'ul'
          out.push('<' + tag + '>' + items.map((it) => {
            const inner = blocks(it)
            // A tight item is one paragraph: drop its <p> so lists render compact.
            return '<li>' + (/^<p>[\s\S]*<\/p>$/.test(inner) && inner.indexOf('<p>', 1) < 0 ? inner.slice(3, -4) : inner) + '</li>'
          }).join('') + '</' + tag + '>')
          continue
        }
        const para = []
        while (i < lines.length && lines[i].trim() && !isFence(lines[i]) && !isHead(lines[i]) && !isQuote(lines[i]) && !isHr(lines[i]) && !isItem(lines[i]) && !isTable(i)) para.push(lines[i++])
        out.push('<p>' + inline(para.join('\n')) + '</p>')
      }
      return out.join('')
    }
    return blocks(String(src || '').replace(/\r\n?/g, '\n').split('\n'))
  }
  // ---- end markdown → html

  // Zhihu's own fetch wrapper adds the xsrf token and the x-zse signature
  // headers. Find it in the page's webpack registry by a string only that
  // module has, and send every request through it.
  const zfetch = (() => {
    const chunks = window.webpackChunkheifetz
    if (!chunks || typeof chunks.push !== 'function') return null
    let req = null
    chunks.push([[Symbol('chrome-use-zhihu')], {}, (r) => { req = r }])
    if (!req || !req.m) return null
    for (const id of Object.keys(req.m)) {
      let src
      try { src = String(req.m[id]) } catch (e) { continue }
      if (!src.includes('please add fetch polyfill')) continue
      let mod
      try { mod = req(Number(id)) } catch (e) { continue }
      for (const k of Object.keys(mod)) if (typeof mod[k] === 'function') return mod[k]
    }
    return null
  })()
  if (!zfetch) return { error: 'Cannot find the Zhihu fetch client', hint: 'zhuanlan.zhihu.com changed its bundle; this adapter needs updating.' }

  // Resolves to {ok, data} or {ok:false, error, code}; the wrapper rejects with
  // the parsed error body ({error:{message, code}}) plus the HTTP status.
  const call = async (url, method, body, extra) => {
    try {
      const opts = Object.assign({ method: method || 'GET' }, extra || {})
      if (body !== undefined) {
        opts.headers = { 'Content-Type': 'application/json' }
        opts.body = JSON.stringify(body)
      }
      return { ok: true, data: await zfetch(url, opts) }
    } catch (e) {
      const err = (e && (e.error || (e.payload && e.payload.error) || e.payload)) || e || {}
      return { ok: false, status: e && e.status, code: err.code, error: err.message || (e && e.message) || JSON.stringify(e).slice(0, 300) }
    }
  }
  const ZL = 'https://zhuanlan.zhihu.com/api'
  const noSig = { zsAutoSignature: false }

  const me = await call('https://www.zhihu.com/api/v4/me')
  if (!me.ok || !me.data || !me.data.id) return { error: 'Not signed in to zhihu.com', hint: 'Log in at https://www.zhihu.com in this browser, then retry.' }

  // Zhihu articles take h2/h3 only; code blocks go in as <pre lang>, which is
  // what the editor itself produces.
  const content = String(args.html || '') || mdToHtml(markdown, (lang, code) =>
    '<pre lang="' + (lang.replace(/[^\w+#.-]/g, '') || 'text') + '">' + code + '</pre>')
    .replace(/<(\/?)h1>/g, '<$1h2>')
    .replace(/<(\/?)h[4-6]>/g, '<$1h3>')

  // Topics: exact (then case-insensitive) matches from the editor's own
  // topic autocomplete.
  const found = await Promise.all(tagNames.map((q) =>
    call(ZL + '/autocomplete/topics?token=' + encodeURIComponent(q) + '&max_matches=5&use_similar=0&topic_filter=1')))
  const topics = []
  const skippedTags = []
  tagNames.forEach((name, i) => {
    const rows = (found[i].ok && Array.isArray(found[i].data)) ? found[i].data : []
    const hit = rows.find((t) => t.name === name) || rows.find((t) => String(t.name).toLowerCase() === name.toLowerCase())
    if (hit && topics.length < 3 && !topics.some((t) => t.id === hit.id)) topics.push(hit)
    else skippedTags.push(name)
  })
  if (!draftOnly && !topics.length) {
    return { error: 'None of the topics exist on Zhihu: ' + tagNames.join(', '), hint: 'Publishing needs at least one existing topic (话题).' }
  }

  const created = await call(ZL + '/articles/drafts', 'POST', { title, content, table_of_contents: false, delta_time: 0 }, noSig)
  if (!created.ok || !created.data || !created.data.id) return { error: 'Could not create the draft: ' + (created.error || 'no id returned') }
  const id = String(created.data.id)
  const draftUrl = 'https://zhuanlan.zhihu.com/p/' + id + '/edit'
  // The create call can drop fields on some accounts; write them once more.
  const patched = await call(ZL + '/articles/' + id + '/draft', 'PATCH', { title, content, table_of_contents: false, delta_time: 1 }, noSig)
  if (!patched.ok) return { error: 'Draft ' + id + ' created but saving its body failed: ' + patched.error, hint: 'Check ' + draftUrl, id, url: draftUrl, status: 'draft' }

  const usedTags = []
  for (const t of topics) {
    const r = await call(ZL + '/articles/' + id + '/topics', 'POST', t)
    if (r.ok) usedTags.push(t.name)
    else skippedTags.push(t.name + ' (' + r.error + ')')
  }
  const base = { id, tags: usedTags, skipped_tags: skippedTags }
  if (draftOnly) return Object.assign({ ok: true, url: draftUrl, status: 'draft' }, base)
  if (!usedTags.length) return Object.assign({ error: 'Could not bind any topic; not publishing', hint: 'Finish it at ' + draftUrl, url: draftUrl, status: 'draft' }, base)

  // The body the editor's publish button posts (see its PublishPanel): one
  // /api/v4/content/publish call with action "article".
  const settings = {
    commentPermission: 'anyone',
    disclaimer_type: 'none',
    disclaimer_status: 'close',
    table_of_contents_enabled: false,
    content,
    title,
    canReward: false,
    commercial_report_info: { commercial_types: [] },
  }
  const text = content.replace(/<[^>]+>/g, '')
  const data = {
    extra_info: { publisher: 'pc', pc_business_params: JSON.stringify(settings) },
    draft: { disabled: 1, id, isPublished: false },
    commentsPermission: { comment_permission: 'anyone' },
    creationStatement: { disclaimer_type: 'none', disclaimer_status: 'close' },
    contentsTables: { table_of_contents_enabled: false },
    commercialReportInfo: { isReport: 0 },
    appreciate: { can_reward: false, tagline: '' },
    hybridInfo: {},
    hybrid: { html: content, textLength: Array.from(text).length },
    title: { title },
  }
  const pub = await call('https://www.zhihu.com/api/v4/content/publish', 'POST', { action: 'article', data })
  if (!pub.ok) {
    return Object.assign({
      error: 'Draft saved but publish failed: ' + pub.error + (pub.code ? ' (code ' + pub.code + ')' : ''),
      hint: pub.code === 4031
        ? 'Zhihu wants account verification (phone/real-name) first; do it by hand, then publish ' + draftUrl
        : 'Finish it at ' + draftUrl + '. Do not re-run: that would create a second draft.',
      url: draftUrl,
      status: 'draft',
    }, base)
  }
  const p = (pub.data && (pub.data.publish || (pub.data.data && pub.data.data.publish))) || {}
  return Object.assign(base, {
    ok: true,
    url: p.url || 'https://zhuanlan.zhihu.com/p/' + id,
    status: 'published',
  })
}
